COLLDATA("tadabburur","ur",[[285,"§الإسراء\ndeeds\nاس سبب کا تعین کیجئے جو آپ کو برائی پر اکساتا ہو پھر اس سے محتاط ہوجائیے.\nکسی یتیم کی کفالت کیجئے یا کسی خیراتی ادارے کا تعاو ن کرکے یتیموں کی کفالت میں ہاتھ بٹائیے.\nجن باتوں کا آپ کو علم نہ ہو،ان کے بارے میں یہ کہنے کی عادت ڈالئے:میں نہیں جانتا،مجھے نہیں معلوم.\nguid\nان اسباب ووسائل سے بھی دوررہئے جو آپ کو فحش اور منکر کاموں کے قریب کرسکتے ہیں اس لئے کہ جو چراگاہ کے آس پاس چرےگا یقینا وہ اس میں بھی داخل ہوسکتا ہے.\nآپ نے اللہ تعالیٰ سے یا اس کی مخلوق سے جو عہد وپیمان کئے ہیں‘قیامت کے دن آپ سے ان کے بارے میں پوچھاجائیگا چنانچہ وعدے پورے کیا کیجئے.\nقیامت کے دن اللہ تعالیٰ کے سامنے آپ سے ان اعضاء(کان،آنکھ اور دل)کے بارے میں بھی بازپرس ہوگی۔سچ تو یہ ہے کہ ان کی اہمیت وہی جان سکتا ہے جو ان سے یا ان میں سے کسی عضو سے محروم ہوگیا ہو لہذا آپ ان کا استعمال اللہ کی اطاعت میں کیجئے.\nrefl\nوَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومٗا مَّحۡسُورًا ٢٩\n(ولا تجعل يدك مغلولة إلى عنقك)یعنی اپنے ہاتھ کو گردن کی طرف بندھاہوا نہ رکھ دو۔یہ دراصل انتہائی درجہ کی بخیلی کے معنی میں استعارہ ہے۔گویا بخیل نے خرچ کرنے سے اپنے ہاتھ کو روک لیا اور اسے گردن سے باندھ دیا۔(ولا تبسطها كل البسط)یعنی اسے پوری طرح کھول بھی نہ دو۔ اس میں انتہائی درجہ کی فیاضی کی طرف اشارہ ہے۔ چنانچہ اللہ تعالیٰ نے دونوں انتہائی صفات سے منع کرکے اعتدال کا حکم دیا ہے جیساکہ فرمایا: ﴿وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا﴾ [الفرقان: ۶۷] (ابن جزی: ۱؍۴۸۶)\nاللہ تعالیٰ نے اس شریعت کو معتدل بنایا ہے۔اس کی کوئی مثال دیجئے.\nإِنَّ رَبَّكَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا ٣٠\nیعنی اللہ تعالیٰ اچھی طرح ہر اس شخص کے بارے میں جانتااور دیکھتا ہے کہ کون مالداری کا مستحق ہے او ر کون فقیری کا۔ کیونکہ کچھ بندے ایسے ہیں جن کے لئے فقیری ہی بہتر ہے۔اگر وہ مالدار ہوجائیں تو ان کا دین خراب ہوجائیگا۔اور کچھ بندے ایسے ہیں جن کے لئے مالداری ہی بہتر ہے۔اگر وہ فقیر ہوجائیں تو ان کا دین خراب ہوجائیگا۔ بعض کے حق میں مالداری بطور مہلت اور فقیری بطور سزاہوتی ہے۔دونوں کے شر سے اللہ کی پناہ!(ابن کثیر: ۳؍۳۷)\nاس آیت کو “خبیر” اور “بصیر ”کی صفات سے ختم کرنے کی کیا وجہ ہے؟\nوَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقٖۖ\nیہ آیت کریمہ اس بات پر دلالت کرتی ہے کہ اللہ تعالیٰ والد کے اپنی اولاد پر شفیق ہونے کے مقابلہ میں اپنے بندوں پر زیادہ مہربان ہے۔(ابن کثیر: ۳؍۳۷)\nآپ پر سب سے زیادہ مہربان کون ہے؟آپ کا رب یا آپ کے والدین؟\nوَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ\nزنا کے قریب جانے کی ممانعت،زنا کرنے کی ممانعت سے زیادہ بلیغ ہے اس لئے کہ زنا کے قریب جانے کی ممانعت زنا کے تمام مقدما ت اور اس کے اسباب کو شامل ہے کیونکہ اگر کوئی مخصوص چراگاہ کے آس پاس پھرتا ہے تو ہوسکتا ہے وہ چراگاہ میں داخل ہوجائے۔خاص طو ر پر جبکہ اکثر لوگوں کے اندر زنا کے قوی اسباب ہوتے ہیں۔(سعدی: ۴۵۷)\nزنا کے قریب نہ جاؤ اور زنا نہ کرو۔دونوں کے درمیان کیا فرق ہے؟ نیز ممانعت میں کون زیادہ بلیغ اور سخت ہے؟\nوَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَسَآءَ سَبِيلٗا ٣٢\nاللہ تعالیٰ نے زنا کی برائیاں بیان کرتے ہوئے فرمایاکہ وہ بے حیائی ہے۔یعنی زنا عقل،شریعت اور فطرت انسانی کے نزدیک بہت بڑی برائی ہے کیونکہ یہ اللہ تعالیٰ او ر عورت،اس کے گھروالوں اور اس کے شوہر کے حق میں حرمت کی پامالی،شوہر کے بستر کو خراب کرنااو ر نسب وغیرہ کے اختلاط کا سبب ہے اور اس میں کئی طرح کی خرابیاں پائی جاتی ہیں۔ (السعدی؍۴۵۷)\nوہ کون سے اسباب ہیں جن کی وجہ سے زنا کو بے حیائی کہا گیا ہے؟\nوَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولٗا ٣٦\nیہ ایک عظیم اخلاقی ادب اور بڑی عقلی اصلاح ہے۔امت کو چاہئے کہ وہ عقلی مراتب کے درمیان فرق سمجھے، اس طور پر کہ معلوم شدہ،گمان والی اور وہم والی چیزوں کے درمیان اختلاط کا شکار نہ ہوں۔ (ابن عاشور: ۱۵؍۱۰۱)\nآیت کریمہ میں حسن اخلاق اور عقلی اصلاح کی طرف رہنمائی ہے۔اس کی وضاحت کیجئے.\nإِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ ٱلۡجِبَالَ طُولٗا ٣٧\nیعنی تمہارے پاس اتنی طاقت نہیں ہے کہ تم اس انتہا تک پہنچ سکوبلکہ تم ایک عاجز بندے ہو،اوپر،نیچے ہر طرف سے تم گھیرے میں ہو اور گھیراؤ میں رہنے والا شخص کمزور اورپابندى ميں محصور ہوتا ہے لہذا کسی طور پر تمہارے لئے تکبر مناسب نہیں ہے۔(القرطبی: ۱۳؍۸۳)\nعاجز وکمزور بندے کے لئے تکبر کیوں مناسب نہیں ہے؟\nwords\nمَلُومًاجس کو لوگ ملامت کرتے ہوں/ مذمت کرتے ہوں.\nمَحسُورًاتہي دست نادم / اپني فضول خرچي پر پريشان.\nوَيَقدِرُوہ تنگ کرتا ہے.\nإِملاقٍفقر.\nوَلا تَقفُاورپيچھے نہ پڑ.\nمَرَحًاحيلہ باز متکبر."],[286,"§الإسراء\ndeeds\nقرآن کی کوئی سورت پڑھئے جو آپ کو آخرت کی یاد دلادے.\nاللہ تعالیٰ سے اس کے دوناموں“الحلیم” (بردبار)اور “الغفور” (بہت بخشنے والا)کے واسطے سے دعائیں مانگئے کہ وہ آپ کے ساتھ حلم کا معاملہ کرے اور آپ کے گناہوں کو بخش دے.\nغفلت کے شر سے اللہ کی پناہ مانگا کیجئے.\nguid\nسب سے زیادہ گناہ والی بری بات اللہ تعالیٰ کی طرف غلط بات منسوب کرنا ہے.\nقرآن میں تدبر اور فہم کی توفیق نہ ملنا گناہو ں کا نتیجہ بھی ہوسکتا ہے چنانچہ جلدی سے توبہ اور بکثرت استغفار کیجئے.\nاللہ تعالیٰ کا ذکر جو خصوصیت سے کلمہ توحید اور قرآن کریم پر مشتمل ہو،وہ شیطان سے ہماری حفاظت کا اہم ذریعہ ہے.\nrefl\nأَفَأَصۡفَىٰكُمۡ رَبُّكُم بِٱلۡبَنِينَ وَٱتَّخَذَ مِنَ ٱلۡمَلَٰٓئِكَةِ إِنَٰثًاۚ إِنَّكُمۡ لَتَقُولُونَ قَوۡلًا عَظِيمٗا ٤٠\nاللہ تعالیٰ نے اس الزام کو صرف ان کی بات قرار دیا ہے چونکہ یہ ایسی بات ہے جوبغیر دیکھے کہی گئی ہے۔اگر اس کا کہنے والا ذرا بھی سوچ بچار کرتا تو خود ہی سمجھ جاتا کہ یہ عقل میں آنے والی بات نہیں ہے۔(ابن عاشور: ۱۵؍۱۰۸)\nمشرکین کے اس الزام کہ “فرشتے اللہ کی بیٹیاں ہیں” کو آیت کریمہ نے ان کے قول سے تعبیر کیوں کیا ہے؟\nتُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا ٤٤\n\"لا تعلمون\" پر(لا تفقهون) فعل کو ترجیح دینے میں اس بات کی طرف اشارہ ہے کہ جس علم کی نفی کی گئی ہے وہ بڑا ہی دقیق ہے۔ (ابن عاشور: ۱۵؍۱۱۵)\nیہاں اللہ تعالیٰ نے \"لا تعلمون\" نہ کہہ کر(لا تفقهون)کیوں کہاہے؟\nوَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ جَعَلۡنَا بَيۡنَكَ وَبَيۡنَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ حِجَابٗا مَّسۡتُورٗا ٤٥\nحجاب کو “شیء مستور” سے متصف کرنے میں دراصل جنس ِحجاب کی حقیقت میں مبالغہ ہے۔یعنی ایسا حجاب جس سے انتہائی درجہ کا ستر ہو گویا کہ وہ خود کسی دوسرے ستر سے ڈھکا ہوا ہو۔یا اس سے مراد ایسا حجاب ہے جو معروف حجابوں کی جنس سے جدا ہے۔ایسا حجاب جسے آنکھیں نہ دیکھ سکیں۔ (ابن عاشور: ۱۵؍۱۱۷)\nآیت کریمہ میں حجاب کو شیء مستور سے متصف کرنے میں کیا فائدہ ہے؟\nوَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ\nیعنی ان کے دلوں پر ایسے پردے اور ڈھکن پڑے ہوئے ہیں جن کی وجہ سے وہ قرآن کو نہیں سمجھ پارہے ہیں البتہ سن رہے ہیں جس سے ان پر حجت قائم ہوجا رہی ہے۔(السعدی؍۴۵۹)\nدلوں پر پردے یا ڈھکن پائے جانے کی کیا علامت ہے؟\nوَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ\n(وفي آذانهم وقرًا) یعنی اللہ تعالیٰ نے ان دشمنان ِاسلام ومشرکین کے کانوں کو اس طرح بوجھل بنادیا ہے کہ وہ قرآن کو اس وقت بالکل نہیں سنتے تھے جب ان پر تلاوت کی جاتی تھی اور سترپوش حجاب اور پردوں سے یہی سب مراد ہے۔اور کان میں ڈاٹ کا پڑنا یہ اللہ کی طرف سے ان لوگوں کے لئے عذاب ہے جو اپنی سابقہ برائیوں کی وجہ سے قرآن کے ذریعہ ہدایت سے محروم ہوگئے ہیں۔یہ ان پر اللہ کی طرف سے کوئی ظلم نہیں ہے بلکہ انہوں نے خود اپنے اوپر ظلم کیا ہے کیونکہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم او ر آپ کی لائی ہوئی شریعت سے بغض ودشمنی کی اور آپ اور آپ کی لائی ہوئی توحید اور دین حق سے انہوں نے جنگ کی۔ (الجزائری: ۳؍۱۹۹)\nآیت میں اس شخص کے لئے وہ کون سی سزاہے جو آپ صلی اللہ علیہ وسلم کی لائی ہوئی شریعت سے بغض اور دشمنی کرے.\nوَإِذَا ذَكَرۡتَ رَبَّكَ فِي ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡاْ عَلَىٰٓ أَدۡبَٰرِهِمۡ نُفُورٗا ٤٦\nابوالجوزاء اَوس بن عبداللہ رحمہ اللہ نے فرمایا: “لا الہ الا اللہ” سے بڑھ کر اور کوئی چیز ایسی نہیں ہے جو دل کے قریب ہونے سے شیطان کو زیادہ بھگانے والی ہو۔ پھر انہوں نے اس آیت کی تلاوت کی (وإذا ذكرت ربك في القرآن وحده ولوا على أدبارهم نفورًا)-(القرطبی: ۱۳؍۹۵)\nشیطان کو اپنے دل کے قریب آنے سے کیسے بھگائیں گے؟\nنَّحۡنُ أَعۡلَمُ بِمَا يَسۡتَمِعُونَ بِهِۦٓ\nیعنی ہم نے ان کو قرآن کے سننے کے وقت اس سے فائدہ اٹھانے سے روک دیا ہے کیونکہ ہم ان کے برے ارادوں کا علم رکھتے ہیں۔وہ چاہتے ہیں کہ کوئی چھوٹی سی بات ہی ہاتھ آجائے تاکہ اس کے ذریعہ اس میں عیب جوئی کریں۔ان کا قرآن سننا طلب ہدایت اور قبول دین کے لئے نہیں بلکہ اس کے برعکس اسے نہ ماننے کا تہیہ کئے ہوئے ہیں اور جن کا یہ حال ہو انہیں قرآن سننا کوئی فائدہ نہیں دیگا۔ (السعدی؍۴۵۹)\nقرآنی آیت سنتے وقت قرآن سے فائدہ حاصل کرنے کا سب سے بہتر طریقہ کیا ہے؟\nwords\nمَلُومًاجس کو لوگ ملامت کرتے ہوں/ مذمت کرتے ہوں.\nمَدحُورًااللہ کي رحمت سے دور.\nأَفَأَصفَاكُمکيا اس نے تمہيں منتخب کرليا ہے.\nصَرَّفنَاہم نے مختلف اسلوب رکھے/ ہم نے وضاحت کردي.\nأَكِنَّةًڈھکن /پردے.\nوَقرًابہرا پن /سماعت کي گراني.\nوَرُفَاتًابکھرے ہوئے أجزاء."],[287,"§الإسراء\ndeeds\nاپنے بھائی اور ساتھی سے اچھی گفتگو کیجئے تاکہ آپ دونوں کے بیچ الفت ومحبت پروان چڑھے.\nشیطانی وسوسوں سے اللہ کی پناہ مانگئے.\nرسول اللہ صلی اللہ علیہ وسلم کی فرمانبرداری کرتے ہوئے آج ہی اپنی وصیت لکھ لینے کی کوشش کیجئے.\nguid\nاپنی زبان کواچھی بات کا عادی بنائیے.\nاللہ تعالیٰ سے محبت کرنا،اس سے امید رکھنا او ر اسی سے ڈرنا،دل کے یہ تینوں اعمال ہر خیر کی بنیاد ہیں،اسی لئے اللہ نے اپنے مقرب بندوں کی یہ صفات بتائی ہیں.\nبرائی کا بڑھ جانا تباہی کا پیش خیمہ ہے.\nrefl\nوَيَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰٓ أَن يَكُونَ قَرِيبٗا ٥١\nقیامت کے وقت کی تعیین کا کوئی فائدہ نہیں۔اس کا فائدہ اور اس کا دارومدار تو اس کے اقرار،اس کی تحقیق اور اس کے اِثبات میں ہے ورنہ حقیقت یہ ہے کہ جس طرح اسے ضرور آنا ہے اس اعتبار سے وہ قریب ہی ہے۔(السعدی: ۴۶۰)\nمشرکو ں کا قیامت کے وقت کے بارے میں سوال بے محل ہے۔ایسا کیوں؟\nيَوۡمَ يَدۡعُوكُمۡ فَتَسۡتَجِيبُونَ بِحَمۡدِهِۦ وَتَظُنُّونَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗا ٥٢\nکیونکہ انسان اگر دنیا میں اور قبر میں ہزاروں سال ٹھہرارہے تو وہ اسے قیامت کی مدت کے مقابلہ میں تھوڑاہی شمار کیا جائیگا۔امام قتادہ رحمہ اللہ فرماتے ہیں: قیامت کے مقابلہ میں یہ لوگ دنیا کی مدت کو بہت حقیر سمجھیں گے۔ (البغوی: ۲؍۶۸۷)\nقیامت کے دن بندہ ایسا کیوں سمجھے گا کہ دنیا میں وہ بہت تھوڑا رہا؟\nوَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ\nاگر دو اچھے امور درپیش ہوں اور ان دونوں میں جمع وتطبیق ممکن نہ ہو تو ان میں جو بہتر ہو اس کو ترجیح دی جائے اور اچھی بات ہمیشہ اچھے اخلاق او ر عمل صالح کی دعوت دیتی ہے اس لئے جسے اپنی زبان پر قابو ہے اس کے تمام معاملات اس کے اختیار میں ہیں۔ (السعدی؍۴۶۰)\nبہتر اور سب سے بہتر قول کے درمیان کیا فرق ہے؟اور ہمیں کس کا حکم دیا گیا ہے؟\nوَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ\nیعنی شیطان بندوں کے دین ودنیا خراب کرکے ان کے درمیان فساد پھیلانا چاہتا ہے۔اور اس فساد کی دوا یہ ہے کہ وہ بری باتوں میں شیطان کی پیروی نہ کریں جن کی طرف شیطان دعوت دیتا ہے۔اور آپس میں نرم رویہ اختیار کریں تاکہ شیطان کی ریشہ دوانیوں کا قلع قمع ہو جو اُن کے درمیان فساد کا بیج بوتا رہتا ہے اس لئے کہ شیطان ان کا حقیقی دشمن ہے او ر ان پر لازم ہے کہ وہ شیطان کے خلاف برابر لڑائی کرتے رہیں۔ (السعدی؍۴۶۰)\nآپ کے اور لوگو ں کے بیچ دوران گفتگو شیطان مداخلت کرتا رہتا ہے۔ آپ اس کا علاج کیسے کریں گے؟\nوَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلۡإِنسَٰنِ عَدُوّٗا مُّبِينٗا ٥٣\nاس تعلق سے ادب سکھانے کا سب سے اہم مقصد یہ ہے کہ امت آپس میں ایک دوسرے کے ساتھ حسن سلوک اور نرم گفتگو سے پیش آئے کیونکہ بات ہی سے مقصد کا پتہ چلتا ہے۔پھر اس بارے میں بھی ادب سکھایا گیا ہے کہ مشرکوں سے بحث ومباحثہ کرتے وقت ایسی باتوں سے اجتناب کریں جن سے لڑائی جھگڑا یا نفرت کا اندیشہ ہو او ر اس کی وجہ سے مشرکوں کی ہٹ دھرمی مزید بڑھ جائے او ر پھر یہی ان کے اور ان کے دشمن کے درمیان شیطان کا کچوکا بن جائے۔ (ابن عاشور: ۱۵؍۱۳۲)\nآیت میں سب سے اہم مقصد کیا ہے؟\nأُوْلَٰٓئِكَ ٱلَّذِينَ يَدۡعُونَ يَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِيلَةَ أَيُّهُمۡ أَقۡرَبُ وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ\nخوف ورجاء یعنی ڈر اور امید کے بغیر عبادت پوری نہیں ہوتی چنانچہ خوف کی وجہ سے بندہ منع کردہ چیزوں سے باز رہتا ہے اور امید کی وجہ سے نیک کام کثرت سے کرتا ہے۔(ابن کثیر: ۳؍۴۶)\nمومن کی زندگی میں خوف ورجاء کی کیا اہمیت ہے؟\nوَإِن مِّن قَرۡيَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَبۡلَ يَوۡمِ ٱلۡقِيَٰمَةِ أَوۡ مُعَذِّبُوهَا عَذَابٗا شَدِيدٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا ٥٨\nعبداللہ بن مسعود رضی اللہ عنہ نے فرمایا: جب بھی زنا اور سود جیسی مہلک بیماریاں کسی بستی میں ظاہر ہوتی ہیں تو اللہ انہیں ہلاک کردیتا ہے۔(القرطبی: ۱۳؍۱۰۷)\nاللہ تعالیٰ بستیوں کو کب ہلاک کرتا ہے؟\nwords\nفَسَيُنغِضُونَوہ عنقريب ٹھٹھہ کرتے ہوئے حرکت ديں گے.\nيَنزَغُوہ خراب کرتا ہے.\nيَبتَغُونَوہ طلب کرتے ہيں.\nالوَسِيلَةَقربت اطاعت گزاري.\nالكِتَابِلوح محفوظ.\nمَسطُورًالکھا ہوا."],[288,"§الإسراء\ndeeds\nایک پیغام کے ذریعہ لوگوں کو گانے بجانے اور موسیقی کے خطرات سے آگاہ کیجئے اور بتائیے کہ یہ شیطانی چال ہیں.\nآج صبح وشام کے اذکار،کھانے سے پہلے اور بعد کے اذکار اور گھر میں آنے اور باہر جانے کے اذکار پوری پابندی سے پڑھئے.\nاللہ تعالیٰ سے دعا کیجئے کہ وہ آپ کو اپنے ان بندوں میں شامل کرلے جن پر شیطان کا کوئی زور نہیں چلتا.\nguid\nاللہ تعالیٰ بندوں کے معاملہ میں کتنا بردبار ہے! وہ اس کی نافرمانی کئے جاتے ہیں حالانکہ وہ انہیں گھیرے ہوئے ہے.\nجو اپنے مال،اولاد اور کھانے پینے میں شریعت کے احکامات کی پاسداری نہیں کرتا تو ان چیزوں میں شیطان اس کا شریک بن جاتا ہے.\nان لوگوں کے او صاف جانئے جن پر شیطان کا بس نہیں چلتا اور کوشش کیجئے کہ آپ بھی ان میں سے بن جائیں.\nrefl\nوَءَاتَيۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةٗ فَظَلَمُواْ بِهَاۚ وَمَا نُرۡسِلُ بِٱلۡأٓيَٰتِ إِلَّا تَخۡوِيفٗا ٥٩\nاللہ نے یہاں قوم ِثمود اور ان کی نشانیو ں کا خصوصی ذکر اس لئے کیا کیونکہ ان کا معاملہ عربوں میں بہت مشہور تھا اور چونکہ ان کی ہلاکت کے آثار بلاد عرب میں جہاں پائے جاتے ہیں وہاں سے اہل ِمکہ بہت قریب ہیں اور مکہ اور شام کے درمیان اپنے تجارتی سفروں میں آتے جاتے وقت ان کا مشاہدہ بھی کرتے رہتے ہیں۔ (ابن عاشور: ۱۵؍۱۴۴)\nآیت کریمہ میں قوم ِثمود کا ذکر خاص طور سے کیوں کیا گیا ہے؟\nوَمَا جَعَلۡنَا ٱلرُّءۡيَا ٱلَّتِيٓ أَرَيۡنَٰكَ إِلَّا فِتۡنَةٗ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ فِي ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنٗا كَبِيرٗا ٦٠\nآپ صلی اللہ علیہ وسلم نے کفار مکہ کو اسراء اور شجرۂ زقوم کے بارے میں خبر دی تو ان میں سے ایک گروہ نے اس کا انکار کردیا اور یہ گمان کر بیٹھے کہ یہ عقل انسانی کے خلاف ہے تو اس وقت اللہ تعالیٰ نے یہ آیت نازل فرمائی: (وما جعلنا الرؤيا التي أريناك إلا فتنة للناس والشجرة الملعونة في القرآن)...یعنی ایسا ہم نے لوگوں کو آزمانے کے لئے کیا ہے تاکہ مومن اور کافر کی تمییز ہوجائے۔ اسی طرح آپ صلی اللہ علیہ وسلم نے انہیں یہ خبر دی کہ آپ صلی اللہ علیہ وسلم نے جنت و جہنم کا بھی مشاہدہ کیا ہے اور یہ انہیں خوف دلانے کے لئے تھا جیسا کہ اللہ تعالیٰ نے آخر میں فرمایا: (وَنُخَوِّفُهُم فَمَا يَزِيدُهُم إِلاَّ طُغيَانًا كَبِيرًا). (ابن تیمیہ: ۴؍۲۳۵)\nلوگوں کی آزمائش کی خاطر نبی صلی اللہ علیہ وسلم نے جوکچھ دیکھا اور اس کی خبر دی وہ کیسا تھا؟ آیت کی روشنی میں اس کی وضاحت کریں.\nوَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنٗا كَبِيرٗا ٦٠\n(نخوفهم)اور(يزيدهم) میں ،فعل ِمضارع‘ لایا گیا ہے تاکہ خوف وڈر کے باربار آنے کا تقاضہ کرے او ر جب جب نئے طور پر انہیں ڈرایا گیا ایک نئے انداز میں ان کی سرکشی مزید بڑھ کر سامنے آئی۔(ابن عاشور: ۱۵؍۱۴۹)\nآیت کریمہ میں (نخوفهم)اور(يزيدهم) کو فعل مضارع سے کیوں ذکر کیا گیا ہے؟\nقَالَ أَرَءَيۡتَكَ هَٰذَا ٱلَّذِي كَرَّمۡتَ عَلَيَّ لَئِنۡ أَخَّرۡتَنِ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَأَحۡتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلٗا ٦٢\n(لأحتنكن ذريته)مطلب یہ ہے کہ ان پر مسلط ہوکر انہیں اپنا تابع بناؤں گا اور یہ لفظ “تَحْنِيْكُ الدَّابَّة”سے ماخوذ ہے جس کا مطلب یہ ہوتا ہے کہ جانور کے جبڑے میں رسی ڈال کر اسے اپنے قابو میں کرنا۔ (ابن جزی: ۱؍۴۹۱)\nشیطان کا انسانوں پر قابو پانے کا کیا مطلب ہے اور اس کی کیا علامت ہے؟\nوَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ مِنۡهُم بِصَوۡتِكَ\nشیطان کی آواز ہر وہ داعی ہے جو اللہ کی معصیت کی طرف لوگوں کو بلائے۔عبداللہ بن عباس رضی اللہ عنہما اور امام مجاہد رحمہ اللہ سے روایت ہے کہ:اس سے مراد گانا،بانسری اور لہوولعب ہیں۔ (القرطبی: ۱۳؍۱۱۸)\nشیطان اپنی آواز سے کیسے قابو میں کرتاہے؟\nوَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ مِنۡهُم بِصَوۡتِكَ وَأَجۡلِبۡ عَلَيۡهِم بِخَيۡلِكَ وَرَجِلِكَ\nہر وہ گفتگو جس میں اللہ کی اطاعت نہ ہو اور ہر وہ آواز جو بانسری یا حرام دف اور ڈھول کی ہوتو وہ شیطان کی آواز ہوگی۔ اور اللہ تعالیٰ کی معصیت میں قدم اٹھانے والا ہر شخص شیطان کا پیادہ ہے۔ اور اللہ کی معصیت میں سواری کرنے والا ہر شخص شیطان کا سوار ہوگا۔ (ابن قیم: ۲؍۱۴۲–۱۴۳)\nشیطان کی آواز ، اس کے سوار اور پیادے سے کیا مراد ہے؟\nوَشَارِكۡهُمۡ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِ وَعِدۡهُمۡۚ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا ٦٤\nمال میں شیطان کے شریک ہونے کا مطلب سود کے ذریعہ اس کا کمانا ہے۔اور گناہوں کی جگہوں میں اسے خرچ کرنا ہے۔اور اولاد میں شرکت کرنے کا مطلب یہ ہے کہ انہیں زنا میں ملوث کرے اور اولاد کا نام عبدالشمس،عبدالحارث وغیرہ مشرکانہ نام رکھنے پرمجبور کرے۔(ابن جزی: ۱؍۳۹۲)\nشیطان بنی آدم کے مال واولاد میں شریک ہوتاہے۔اس کی کچھ شکلیں بتائیے.\nwords\nأَرَأَيتَكَمجھے بتاديں.\nلأَحتَنِكَنَّميں ضرور ان پر غالب آؤں گا.\nمَوفُورًاوافر.\nوَاستَفزِزجلدي کر/ ساتھ ملا لے.\nوَأَجلِبجمع کرلے/ انہيں آواز دے.\nبِخَيلِكَ وَرَجِلِكَمعصيت الٰہي ميں سوار اور پيادہ لشکر."],[289,"§الإسراء\ndeeds\nاپنی کسی پریشانی کو یاد کیجئے جس سے اللہ نے آپ کو نجات دی اور اللہ کے لئے سجدۂ شکر ادا کیجئے.\nاللہ سے دعا مانگئے کہ آپ کو نامہ اعمال دائیں ہاتھ میں دیا جائے.\nرسول اللہ صلی اللہ علیہ وسلم کو بھی اپنے لئے ثابت قدمی مانگنے کی ضرورت پڑی چنانچہ آپ بھی یہ دعا مانگئے: “اَللّٰهُمَّ اِنِّىْ أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ وَالْعَزِيْمَةَ عَلَى الرُّشْدِ”۔اے اللہ! میں تجھ سے دین پر ثابت قدمی او ر ہدایت پر مضبوطی سے جمے رہنے کا سوال کرتاہوں.\nguid\nیہ بندے کی کمزوری کی دلیل ہے کہ اللہ تعالیٰ اسے تکلیف سے نجات دے اور اس کی مصیبت دور کرے مگر جلد ہی وہ غفلت،اللہ کی نافرمانی اور فساد کی طرف پلٹ جاتا ہے.\nرنگ،نسب یا علاقائی بنیاد پر کسی کو بھی حقیر نہ جانئے.\nمجرمین آپ کو دوست نہیں بناسکتے،ہا ں مگر اسی وقت جبکہ آپ ان کی برائیوں میں شریک رہیں.\nrefl\nأَفَأَمِنتُمۡ أَن يَخۡسِفَ بِكُمۡ جَانِبَ ٱلۡبَرِّ أَوۡ يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗا ثُمَّ لَا تَجِدُواْ لَكُمۡ وَكِيلًا ٦٨\nآیت میں اس بات پر تنبیہ ہے کہ خشکی کے اندر امن وسلامتی ایک بہت بڑی نعمت ہے جسے لوگ بھلا بیٹھے ہیں۔اگر زمین کو دھنسادیا جائے تو سب ہلاک ہوجائیں،کوئی نہ بچے۔ جبکہ دریا کی ہولناکی کا معاملہ دوسرا ہے۔(ابن عاشور: ۱۵؍۱۶۲)\nخشکی میں امن وسلامتی بہت بڑی نعمت ہے جسے ہم سب بھولے ہوئے ہیں۔آیت کریمہ نے اس جانب کیسے رہنمائی کی ہے؟\nوَفَضَّلۡنَٰهُمۡ عَلَىٰ كَثِيرٖ مِّمَّنۡ خَلَقۡنَا تَفۡضِيلٗا ٧٠\nاعتقاد کے لائق او ر صحیح بات یہ ہے کہ کسی چیز کو فضیلت دینے کا انحصار عقل پر ہے۔اور تمام شرعی احکامات میں یہی اصل ہے،اسی کے ذریعہ اللہ کی معرفت حاصل ہوتی ہے اور اس کے کلام کو سمجھاجاتا ہے،اس کی نعمتوں تک پہنچاجاسکتا ہے اور اس کے رسولوں کی تصدیق کی جاتی ہے۔لیکن جب بندہ ساری چیزوں کو اس کے ذریعہ سمجھنے سے قاصر ہوجاتا ہے تو رسولوں کو بھیجاجاتا ہے اور کتابیں نازل کی جاتی ہیں۔پس شریعت کی مثال سورج اور عقل کی مثال آنکھ کی طرح ہے۔ جب صحیح وسالم آنکھ کھلے گی تبھی سورج دیکھے گی اور تمام چیزوں کی تفصیل حاصل کرسکے گی۔ (القرطبی: ۱۳؍۱۲۶)\nاس بات کی وضاحت کیجئے کہ اللہ تعالیٰ نے بنی آدم کو تمام مخلوقات پر کس وجہ سے فضیلت دی ہے؟\nيَوۡمَ نَدۡعُواْ كُلَّ أُنَاسِۢ بِإِمَٰمِهِمۡۖ فَمَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُوْلَٰٓئِكَ يَقۡرَءُونَ كِتَٰبَهُمۡ وَلَا يُظۡلَمُونَ فَتِيلٗا ٧١\n“فتیل” یعنی فیتہ۔اس سے وہ دھاگا مراد ہے جو کھجور کی گٹھلی کے شگاف میں ہوتا ہے۔مفہوم یہ ہے کہ ان کے اعمال میں کچھ بھی ظلم نہیں کیا جائیگا چاہے وہ کم ہوں یا زیادہ۔تھوڑی چیز کے ذکر سے دراصل زیادہ پر تنبیہ ہے۔(ابن جُزی: ۱؍۴۹۳)\nآیت میں فیتہ سے دراصل کیا مراد ہے؟\nوَمَن كَانَ فِي هَٰذِهِۦٓ أَعۡمَىٰ فَهُوَ فِي ٱلۡأٓخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِيلٗا ٧٢\n(هذه) یعنی دنیا اور اندھے پن سے مراد دل کا اندھا ہونا ہے۔یعنی جو دنیا میں ہدایت اور سچائی کے راستے سے اندھا ہوگا وہ قیامت کے دن اندھا یعنی بھلائی کے پانے سے حیران وپریشان ہوگا۔ (ابن جزی: ۱؍۴۹۳)\nدنیا اور آخرت کے اندھے پن سے کیا مراد ہے؟\nوَإِن كَادُواْ لَيَفۡتِنُونَكَ عَنِ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ لِتَفۡتَرِيَ عَلَيۡنَا غَيۡرَهُۥۖ وَإِذٗا لَّٱتَّخَذُوكَ خَلِيلٗا ٧٣\nتاکہ آپ کو پتہ چل جائے کہ وہ لوگ آپ سے صرف اسی حق کی بناپر دشمنی کررہے ہیں جسے لے کر آپ صلی اللہ علیہ وسلم آئے ہیں،ا ن کی دشمنی آپ کی ذات سے نہیں ہے۔(السعدی: ۴۶۴)\nنبی صلی اللہ علیہ وسلم سے مشرکین کی دشمنی کی کیا وجہ تھی؟اور اس بات سے ایک داعی کیا فائدہ اٹھاسکتا ہے؟\nوَلَوۡلَآ أَن ثَبَّتۡنَٰكَ لَقَدۡ كِدتَّ تَرۡكَنُ إِلَيۡهِمۡ شَيۡـٔٗا قَلِيلًا ٧٤\nیہ آیات کریمہ دلالت کرتی ہے کہ بندہ اس بات کا شدید محتاج ہے کہ اللہ تعالیٰ اسے ثابت قدمی سے نوازے رکھے اور یہ کہ بندہ گڑگڑاکر اپنے رب سے دعا کرتا رہے کہ وہ اسے ایمان پر ثابت قدمی عطاکرے۔اور وہ اس مقصد کے حصول کے لئے تمام اسباب اختیار کرنے کی کوشش کرتا رہے کیونکہ نبی صلی اللہ علیہ وسلم مخلوق میں سب سے کامل ہستی ہیں پھر بھی اللہ تعالیٰ نے آپ سے فرمایا: (ولولا أن ثبتناك لقد كدت تركن إليهم شيئًا قليلًا) اور جب نبی صلی اللہ علیہ وسلم کے بارے میں اللہ تعالیٰ کا یہ ارشاد ہے تو دوسروں کے بارے میں کیا کہا جاسکتا ہے!(السعدی: ۴۶۴)\nیہ آیات کریمہ دلالت کرتی ہیں کہ بندہ اس بات کا شدید محتاج ہے کہ اللہ تعالیٰ اسے ثابت قدمی سے نوازے رکھے۔اس کی وضاحت کیجئے.\nإِذٗا لَّأَذَقۡنَٰكَ ضِعۡفَ ٱلۡحَيَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيۡنَا نَصِيرٗا ٧٥\nبندے کے بلند مرتبہ کے مطابق اس کو پے درپے نعمتیں عطاہوتی ہیں۔اسی طرح جب وہ قابل ِملامت فعل انجام دیتاہے تو اس کا گناہ بھی بڑا ہوجاتا ہے اور اس کا جرم کئی گنازیادہ ہوجاتا ہے کیونکہ اللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم کو اپنے اس ارشاد کے ذریعہ سے نصیحت فرمائی ہے حالانکہ آپ ہر گناہ سے پاک اور معصوم ہیں۔(السعدی؍۴۶۴)\nکیا وجہ ہے کہ نبی صلی اللہ علیہ وسلم یا اس امت کے عالم یا داعی کی غلطی۔اگر پائی جائے۔ تو دوسروں کے مقابلہ میں بڑی مانی جائیگی؟\nwords\nحَاصِبًابہت سخت ہوا پتھر برسانے والي.\nقَاصِفًا مِنَ الرِّيحِتوڑ دينے والي بہت سخت ہوا.\nبِإِمَامِهِمجن کي وہ دنيا ميں اقتدا کرتے تھے.\nكَادُواقريب تھے.\nلَيَفتِنُونَكَتاکہ تمہيں فتنہ ميں ڈال ديں."],[290,"§الإسراء\ndeeds\nپانچوں وقت کی نمازیں مسجد میں باجماعت پابندی سے ادا کیا کیجئے خاص طور سے فجر کی نماز.\nآج رات جتنا ممکن ہو قیام اللیل کیجئے،پھر وتر پڑھئے.\nاپنے آپ پر یا اپنے آس پاس والوں پر قرآن کے ذریعہ دم کیجئے.\nguid\nقرآن خصوصیت سے مومنوں کے لئے شفا اور رحمت ہے لہذا آپ اپنی حسی اور معنوی بیماریوں کا اسی کے ذریعہ علاج کیجئے.\nجب بھی حق پرست حق کی تبلیغ کے لئے اٹھ کھڑے ہوتے ہیں تو لازماً باطل کو ختم ہونا ہی پڑتا ہے چاہے وہ جتنا پھل پھول چکا ہو.\nظلم نہ کیجئے کیونکہ آدمی اپنے ظلم کے بقدر ہی قرآن سے محروم کردیا جاتا ہے.\nrefl\nوَإِن كَادُواْ لَيَسۡتَفِزُّونَكَ مِنَ ٱلۡأَرۡضِ لِيُخۡرِجُوكَ مِنۡهَاۖ وَإِذٗا لَّا يَلۡبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلٗا ٧٦\nیعنی اگر انہوں نے آپ کو مکہ سے نکال دیا تو وہ مکہ میں زیادہ دن نہیں ٹھہر سکیں گے چنانچہ جب نبی صلی اللہ علیہ وسلم او ر صحابہ کرام قریش کی ایذارسانی کی وجہ سے مکہ سے مدینہ ہجرت کرگئے تو وہ بھی زیادہ دن مکہ میں نہ رہ سکے اور جنگ بدر میں قتل کردئیے گئے۔(ابن جزی: ۱؍۴۹۴)\nواضح کیجئے کہ جو لوگ دعاۃ اور مصلحین کو تکلیفیں دیتے ہیں،ان کے بارے میں اللہ کی کیا سنت رہی ہے؟\nوَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةٗ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامٗا مَّحۡمُودٗا ٧٩\nصحیح بخاری کے اندر عبداللہ بن عمر رضی اللہ عنہما سے مروی ہے کہ قیامت کے دن لوگ جماعت کی شکل میں ہوں گے۔ہر امت اپنے نبی کے تابع ہوگی اور کہیں گے کہ:ہماری سفارش کردیجئے۔ یہاں تک کہ یہ سفارش نبی صلی اللہ علیہ وسلم تک پہنچ جائیگی۔پس یہی وہ دن ہوگا جب اللہ آپ کو مقام ِ محمود تک پہنچائیگا۔ (ابن عاشور: ۱۵؍۱۸۵)\nمقام محمود سے کیا مراد ہے؟\nوَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةٗ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامٗا مَّحۡمُودٗا ٧٩\nقیام اللیل میں لوگوں سے دور رہ کر تنہائی میں اللہ تعالیٰ سے مناجات ہوتی ہے۔ (القرطبی: ۱۳؍۱۵۱)\nدوسری عبادتوں کے مقابلہ میں قیام اللیل کی کیا خصوصیت ہے؟\nوَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَٰطِلُۚ إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقٗا ٨١\n(إن الباطل كان زهوقًا) یعنی یہی باطل کی صفت ہے۔مگر کبھی کبھی ایسا بھی ہوتا ہے کہ اگر باطل کے مقابلہ میں حق موجود نہ ہو تو باطل عروج پاکر رائج ہوجاتا ہے۔تاہم جب حق آتا ہے تو باطل کمزور ہوجاتا ہے اور اس میں کوئی حرکت باقی نہیں رہتی۔اسی لئے باطل صرف انہی زمانوں اور انہی علاقو ں میں رواج پاتا ہے جو اللہ تبارک وتعالیٰ کی آیات اور اس کے دلائل کے علم سے خالی ہوں۔ (السعدی؍۴۶۵)\nباطل کو طاقت اور مقام ومرتبہ کب ملتا ہے؟\nوَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَٰطِلُۚ إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقٗا ٨١\n(كان) فعل اس بات پر دلالت کرتا ہے کہ مٹ جانا ہی باطل کی پہچان ہے اور اس کی ہمیشہ یہی حالت رہی ہے کہ وہ وقتی طور پر ظاہر ہوتا ہے مگر بالآخر مٹ ہی جاتا ہے۔(ابن عاشور: ۱۵؍۱۸۸)\nآیت کریمہ میں ’کان‘ فعل کس بات کا فائدہ دیتا ہے؟\nوَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ\nوہ شفا جس کو قرآن شامل ہے وہ دلوں کے لئے شفاء عام ہے اور دلوں سے شبہات،جہالت،مذموم انحراف اور گھٹیا مقاصد جیسے امراض کو دور کرتی ہے کیونکہ قرآن علم یقینی پر مشتمل ہے جو ہر قسم کی جہالت اور تما م شبہات کو زائل کردیتا ہے۔اسی طرح وعظ ونصیحت پر مشتمل ہے جو ہر اس شہوت کو ختم کردیتا ہے جس میں اللہ تعالیٰ کے حکم کی مخالفت ہو۔ساتھ ہی قرآن جسموں کے امراض اور تکلیفوں سے شفا کو بھی شامل ہے۔(السعدی؍۴۶۵)\nقرآن دلوں کے لئے شفا ہے۔ اس کی کیا وجہ ہے؟\nوَيَسۡـَٔلُونَكَ عَنِ ٱلرُّوحِۖ قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّي وَمَآ أُوتِيتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِيلٗا ٨٥\nاس آیت میں اس بات کی دلیل ہے کہ جب کسی سے کسی بات کا سوال کیا جائے تو اس کے لئے بہتر ہے کہ وہ لایعنی سوال کا جواب دینے سے گریز کرے اور اس امر میں اس پوچھنے والے کی رہنمائی کرے جس کی اسے زیادہ ضروت ہو اور جو اس کے لئے فائدہ مند ہو۔ (السعدی؍۴۶۶)\nبہت سے لوگ ایسی چیزوں کے بارے میں سوال کرتے ہیں جو نہ ان کے دین کے لئے فائدہ مند ہوتی ہیں اور نہ ان کی دنیا کے لئے۔تو ایسے سوالات کے وقت ایک داعی اور طالب علم کو کیا طریقہ اختیار کرنا چاہئے؟\nwords\nكَادُواقريب تھے.\nتَحوِيلًاتبديلي.\nلِدُلُوكِ الشَّمسِزوال شمس کے وقت.\nغَسَقِ اللَّيلِرات کا اندھيرا.\nوَزَهَقَباطل ہوگيا/ کمزور پڑ گيا.\nزَهُوقًاجسے بقا اور ثبات نہ ہو.\nوَنَأَى بِجَانِبِهِتکبر سے رب کي طاعت سے دور ہوا.\nشَاكِلَتِهِاپنے طريقہ پر."],[291,"§الإسراء\ndeeds\nاللہ تعالیٰ کی آپ پر بہت سی نوازشیں ہیں،ان میں سے پانچ بڑی عنایات کی تعیین کیجئے اور پھر ان پر کثرت سے اللہ کا شکر ادا کیجئے.\nقرآن میں بیان کی ہوئی کوئی مثال پڑھئے اور اس سے کوئی فائدہ نکالئے.\nقرآن کریم کے معانی کا کوئی اچھا سا ترجمہ تلاش کرکے کسی کافر کو دیجئے،ہوسکتا ہے کہ وہ آپ کے ذریعہ مسلمان ہوجائے.\nguid\nاللہ تعالیٰ نے قرآن کریم میں الگ الگ طرح سے نصیحتیں کیں اور مثالیں بیان کی ہیں تاکہ ان کا مقصد حاصل ہوسکے.\nبحث ومباحثہ اور مناظرہ کا فن سیکھئے اور اس کی مشق کیجئے.\nجب بھی آپ مسائل کی سختی سے پریشان ہوں تو سیرت نبوی صلی اللہ علیہ وسلم کا مطالعہ کیجئے تاکہ آپ نبی صلی اللہ علیہ وسلم کے صبر سے سبق لے سکیں.\nrefl\nإِلَّا رَحۡمَةٗ مِّن رَّبِّكَۚ إِنَّ فَضۡلَهُۥ كَانَ عَلَيۡكَ كَبِيرٗا ٨٧\nآپ صلی اللہ علیہ وسلم پر الله كا بڑا فضل و كرم ہے کیونکہ اس نے آپ صلی اللہ علیہ وسلم کو بنی آد م کا سردار بنایااوراِس کتاب عزیز سے سرفراز کیااور مقام محمود سے نوازاہے۔ (القرطبی: ۱۳؍۱۶۹)\nوہ کون سی عمدہ فضیلتیں ہیں جن سے اللہ تعالیٰ نے نبی صلی اللہ علیہ وسلم کو نوازا ہے؟\nقُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا ٨٨\nپوری مخلوق قرآن جیسا کلام لانے سے عاجزآگئی کیونکہ اس میں ایسے الٰہی علوم،واضح دلائل اور عجیب وغریب معانی پائے جاتے ہیں جنہیں لوگ نہ توجانتے تھے اور نہ ہی ان تک پہنچ سکتے ہیں۔پھر یہ ساری چیزیں کمال کو پہنچی ہوئی ہیں اور اکثر لوگوں کا کہنا ہے: وہ لوگ اس کی فصاحت،حسن ترتیب اور اس کے اعجاز کی بہت ساری صورتوں کی وجہ سے عاجز آگئے۔(ابن جزی: ۱؍۴۹۶)\nآیت کی روشنی میں اعجاز قرآن کی بعض وجہیں بیان کیجئے.\nقُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا ٨٨\nیہ اس بات کی قطعی دلیل اور واضح برہان ہے کہ جو کچھ رسول اللہ صلی اللہ علیہ وسلم لے کر آئے ہیں وہ صحیح اور صداقت پر مبنی ہے کیونکہ اللہ تعالیٰ نے تمام جنوں اور انسانوں کو معارضہ کی دعوت دی ہے کہ وہ اس جیسا قرآن بنالائیں اور اس کے ساتھ ہی اللہ تعالیٰ نے ان کو آگاہ بھی فرمایا کہ وہ اس جیسا قرآن نہیں لاسکتے خواہ وہ ایک دوسرے کی مدد ہی کیوں نہ کرلیں۔ او ر یہ سب کچھ اسی طرح واقع ہوا جس طرح اللہ تعالیٰ نے خبر دی تھی۔(السعدی: ۴۶۶)\nآیت کریمہ محمد صلی اللہ علیہ وسلم کی سچائی پر کس طرح دلالت کرتی ہے؟\nقُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا ٨٨\nقرآن اپنے حسن ترتیب،نظم وضبط اور غیب کی خبریں بتانے میں معجزہ ہے،نیز بلاغت وفصاحت کے انتہائی بلند مقام پر پہنچا ہوا ہے جو مخلوق کے کلام کے بالکل مشابہ نہیں ہے کیونکہ قرآن مخلوق نہیں ہے اگر وہ مخلوق ہوتا تو وہ لوگ اس جیسا ضرور بنالاتے۔(البغوی: ۲؍۷۱۴)\nوضاحت کیجئے کہ قرآن میں کتنی طرح کا اعجازپایا جاتا ہے؟\nوَقَالُواْ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ يَنۢبُوعًا ٩٠\nیہ اللہ تعالیٰ کے لئے بہت ہی آسان ہے اگر چاہتا تو کردیتا اور ان کی تمام مانگیں اور طلب پوری کردیتا لیکن اللہ جانتا ہے کہ وہ پھر بھی ہدایت پر نہیں آئیں گے۔(ابن کثیر: ۳؍۶۳)\nاللہ تعالیٰ نے مشرکین کے مطالبات کو پورا کیوں نہیں کیا؟\nأَوۡ تُسۡقِطَ ٱلسَّمَآءَ كَمَا زَعَمۡتَ عَلَيۡنَا كِسَفًا\nیعنی جو آپ نے وعدہ کیا ہے کہ قیامت کے دن آسمان پھٹ کر گرجائیگا اور وہ چاروں طرف سے لٹک جائیگا تو اپنا یہ وعدہ جلدی دنیا میں ہی پورا کردیجئے اور آسمان کو ٹکڑے ٹکڑے کرکے گرادیجئے۔لیکن رحمت اور توبہ کے نبی صلی اللہ علیہ وسلم جو سارے عالم کے لئے رحمت بناکر بھیجے گئے تھے آپ نے اللہ سے ان کے لئے مہلت مانگ لی اور ان کی بات مؤخر کردی کہ ہوسکتا ہے اللہ تعالیٰ ان کی پشتوں سے ایسی نسل پیدا کردے جو صرف اللہ کی عبادت کریں،اس کے ساتھ کسی کو شریک نہ کریں اور حقیقت میں ایسا ہی ہواکیونکہ انہی کی نسل میں ایسے لوگ پیدا ہوئے جو بعد میں اسلام لائے اوراسلام پر قائم و دائم رہے۔(ابن کثیر:۳؍۶۳)\nنبی صلی اللہ علیہ وسلم نے اپنے رب سے ان ہٹ دھرموں پر آسمان کے ٹکڑے گرنے کی دعا کیوں نہ کی،جب کہ خود انہوں نے آ پ سے اس کا مطالبہ کیا تھا؟\nقُل لَّوۡ كَانَ فِي ٱلۡأَرۡضِ مَلَٰٓئِكَةٞ يَمۡشُونَ مُطۡمَئِنِّينَ لَنَزَّلۡنَا عَلَيۡهِم مِّنَ ٱلسَّمَآءِ مَلَكٗا رَّسُولٗا ٩٥\n(قل لو كان في الأرض ملائكة يمشون مطمئنين) یعنی یہ فرشتے زمین میں وطن بناکر مقیم ہوتے (لنزلنا عليهم من السماء ملكًا رسولًا) یعنی میں انہی کی جنس سے رسول بھیجتا کیونکہ دوسری جنس کے مقابلہ میں دل اپنی جنس کی طرف زیادہ مائل ہوتاہے۔(البغوی: ۲؍۷۱۷)\nاللہ تعالیٰ نے تمام انبیاء انسانوں کی ہی جنس میں سے کیو ں بھیجے،فرشتوں میں سے کیوں نہیں بھیجے؟\nwords\nظَهِيرًامددگار.\nصَرَّفنَاہم نے بيان کرديا.\nصَرَّفنَانَوَّعنَا وَبَيَّنَّا.\nيَنبُوعًاجاري چشمہ.\nكِسَفًاٹکڑا.\nقَبِيلًاآنکھوں کے سامنے /آمنے سامنے.\nزُخرُفٍسونا."],[292,"§الإسراء\ndeeds\nاچھی طرح اور مکمل وضوء کیجئے تاکہ وہ آپ کے گناہوں کا کفارہ ہوسکے.\nاللہ سے دعا مانگئے کہ وہ آپ کو اپنے فضل سے دنیاوالوں سے بے نیاز کردے.\nکسی نیکی کے کام میں خرچ کیجئے تاکہ آپ جودوکرم کے عادی بن سکیں.\nguid\nانسان خواہ کتنا ہی سخی اور فیاض ہوجائے،بہرحال اس میں بخل کی صفت ہوتی ہی ہے اور بے شک اللہ تعالیٰ ہی ایسا فیاض، نوازنے والا ہے جو بے حساب دیتا ہے.\nبندے کے دل میں رب کا مقام جتنا بلند ہوگا اتنا ہی مخلوق کا مرتبہ اس کی نظروں میں کم ہوگا.\nتکلیف خواہ کتنی ہی سخت ہو،آپ صبر کیجئے کیونکہ بہرحال اچھا نتیجہ متقیوں کے لئے ہے.\nrefl\nوَمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُمۡ أَوۡلِيَآءَ مِن دُونِهِۦۖ\n(وَمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ) یعنی اگر اللہ تعالیٰ انہیں ہدایت دیتا تو وہ ضرورہدایت پاتے (ومن يضلل فلن تجد لهم أولياء من دونه) یعنی اگر اللہ تعالیٰ گمراہ کردے تو انہیں کوئی ہدایت نہیں دے سکتا۔(القرطبی: ۱۳؍۱۷۸)\nکیا اللہ تعالیٰ کے چاہے بغیر کوئی ہدایت پاسکتا ہے؟\nوَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيٗا وَبُكۡمٗا وَصُمّٗاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ\nجس طرح دنیا کے اندر بے انتہا ذلت و رسوائی اور سزا دینے کے لئےاوندھے منہ کے بل گھسیٹا جاتا ہے بالکل اسی طرح انہیں قیامت کے دن اوندھے منہ کے بل گھسیٹا جائے گا اور یہی تعبیر صحیح ہے جیسا کہ سیدنا انس رضی اللہ عنہ کی حدیث میں ہے: ایک شخص نے دریافت کیا: اے اللہ کے رسول! قیامت کے دن لوگ اوندھے منہ کے بل اٹھائے جائیں گے تو کیا ایسے ہی کافروں کو اٹھایا جائے گا؟ تو آپ نے فرمایا: کیا وہ ذات جو دو ہاتھوں پر چلاسکتا ہے وہ قیامت کے دن منہ کے بل نہیں چلاسکتا؟ جب یہ حدیث قتادہ کو پہنچی تو کہا : میرے رب کی عزت و جلال کی قسم ! کیوں نہیں!(القرطبی: ۱۳؍۱۷۸)\nقیامت کے دن کافروں کو اوندھے منہ کے بل کیسے اٹھایا جائے گا؟ اس کی کیا دلالت ہے؟\nوَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيٗا وَبُكۡمٗا وَصُمّٗاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَٰهُمۡ سَعِيرٗا ٩٧\nجرم کے لئے یہ مناسب سزا ہے کیونکہ انہوں نے گمراہی کو حق کی صورت میں رواج دیا اور حق کو گمراہی کے اوصاف سے متصف کیا چنانچہ انہیں یہ سزا دی گئی ّکہ انہیں پاؤں کے بجائے چہروں کے بَل چلایا گیا۔پھر رسول اللہ صلی اللہ علیہ وسلم اور قرآ ن پاک کے خلاف ان کے باطل پروپیگنڈوں کے جرم میں انہیں اندھا اور گونگا بنادیا گیا اور حق بات سننے سے دوررہنے کے جرم میں بہرا بنادیا گیا۔(ابن عاشور: ۱۵؍۲۱۷)\nقیامت کے دن کافروں کی سزا ان کے جرم کے اعتبار سے ہوگی؟اس کی و ضاحت کیجئے.\nوَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيٗا وَبُكۡمٗا وَصُمّٗاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَٰهُمۡ سَعِيرٗا ٩٧\nاگر اعتراض کیا جائے کہ انہیں اندھا،بہرا اور گونگا کیوں بنایا گیا جبکہ ان کے بارے میں کہا گیا ہے: ﴿وَرَءَا ٱلۡمُجۡرِمُونَ ٱلنَّارَ فَظَنُّوٓاْ﴾ [الكهف: ۵۳]؛ یعنی مجرمین جہنم کو دیکھیں گے؟ یعنی ان کے لئے دیکھنا،بات کرنا اور سننا ثابت ہے؟ تو اس کا جواب یہ ہے کہ انہیں بالکل اسی طرح اٹھایا جائیگا جیسا اللہ تعالیٰ نے بیا ن کیا ہے لیکن وقت کی مناسبت سے یہ سارے اوصاف واپس کردئیے جائیں گے۔ اور دوسرا جواب یہ ہے: عبداللہ بن عباس رضی اللہ عنہما نے فرمایاہے کہ یہاں ان کے اندھے اور گونگے ہونے کا مطلب یہ ہے کہ وہ ایسی چیز نہیں دیکھیں گے جن سے ان کو خوشی ہو اور نہ ہی دلیل سے کوئی بات بول سکیں گے۔ اور ان کے بہرےہونے سے مراد یہ ہے کہ وہ ایسی کوئی چیز نہیں سنیں گے جس سے انہیں خوشی ہو۔امام حسن بصری رحمہ اللہ فرماتے ہیں: یہ اس وقت ہوگا جب انہیں حساب وکتاب کے لئے موقف یعنی میدان محشر میں لایا جائیگا،یہاں تک کہ جہنم میں داخل ہوجائیں گے۔(البغوی: ۲؍۷۱۸)\nاہل ِجہنم کس طرح اندھے،بہراےاور گونگے بناکراٹھائے جائیں گے؟\nوَكَانَ ٱلۡإِنسَٰنُ قَتُورٗا ١٠٠\nیعنی ایسا بخیل جو خرچ کرنے سے اپنے ہاتھ روکے ہوئے ہو۔(البغوی: ۲؍۷۱۹)\nمال کے تعلق سے انسانی فطرت واضح کیجئے اور بتائیے کہ بندہ اس صفت سے کیسے نجات پاسکتا ہے؟\nقَالَ لَقَدۡ عَلِمۡتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ بَصَآئِرَ وَإِنِّي لَأَظُنُّكَ يَٰفِرۡعَوۡنُ مَثۡبُورٗا ١٠٢\nموسیٰ علیہ السلام جو کہ سچے نبی تھے،فرعون کو مخاطب کرکے کہہ رہے ہیں: (لقد علمت ما أنزل هؤلاء إلا رب السماوات والأرض بصائر)؛ تجھے پتہ ہے کہ ان نشانیوں کو آسمانوں او ر زمین کے رب نے بطور نصیحت نازل کیا ہے۔یہ اس بات پر دلالت کرتا ہے کہ فرعون کو اس بات کا علم تھا کہ ان نشانیوں کو اللہ تعالیٰ نے ہی اتارا ہے۔لیکن وہ جہالت کی بنیاد پر نہیں بلکہ اپنے فاسد ارادے اور گھٹیا سوچ کی بناپر اللہ کی مخلوق میں سب سے بڑا ہٹ دھرم اور ظالم تھا۔ (ابن تیمیہ: ۴؍۲۴۸)\nانسان کبھی کبھی جان بوجھ کر گمراہ ہوتا ہے۔آیت کی روشنی میں اس کی وضاحت کیجئے.\nفَأَرَادَ أَن يَسۡتَفِزَّهُم مِّنَ ٱلۡأَرۡضِ فَأَغۡرَقۡنَٰهُ وَمَن مَّعَهُۥ جَمِيعٗا ١٠٣\nمشرکو ں نے نبی صلی اللہ علیہ وسلم اور مسلمانو ں کو مکہ سے نکال دینے کا پختہ ارادہ کررکھا تھا چنانچہ ان کے اسی ارادے کو فرعون کے اس ارادے سے تشبیہ دی گئی ہے جو وہ مصر سے موسیٰ علیہ السلام اور بنی اسرائیل کو نکالنے کے تعلق سے رکھتا تھا۔(ابن عاشور: ۱۵؍۲۲۸)\nمشرکین قریش اور قوم ِفرعون کے درمیان جو مشابہت ہے اس کی وضاحت کیجئے.\nwords\nخَبَتشعلے مدھم پڑ گئے.\nقَتُورًابخل ميں مبالغہ کرنے والا.\nبَصَائِرَدلائل /جو اہل بصيرت کو وحدانيت رباني کا رستہ ديکھاتے ہيں.\nمَثبُورًاہلاک ہونے والا / مغلوب / ملعون.\nلَفِيفًاجمع کرکے."],[293,"§الكهف ، الإسراء\ndeeds\nسورۂ کہف کی ابتدائی دس آیتیں یاد کیجئے کیونکہ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے: “مَن حفِظَ عشَرَ آياتٍ مِن أَوَّلِ سُورَةِ الکَهفِ عُصِمَ مِن الدّجّالِ”۔ (صحیح مسلم) جو سورۂ کہف کی ابتدائی دس آیتیں یاد کرلے،وہ دجال سے محفوظ رہیگا.\nاپنے کچھ ساتھیوں کو اکٹھاکیجئے،پھر آپ میں سے ہر ایک کلام اللہ کی چندآیتیں تلاوت کرے.\nاللہ کے بعض اسماء حسنیٰ کے معانی پر غور کیجئے اور ان کے واسطے سے اللہ سے دعامانگئے.\nguid\nقرآن اللہ کی جانب سے برحق ہے اور قرآن میں جو کچھ نازل ہوا،سب حق ہے.\nٹھہرٹھہر کر قرآن پڑھنا قرآن میں غور وفکرکرنے میں معاون ہوتا ہے.\nقرآن کریم کے ذریعہ ترقی کے درجات اس طرح ہیں: ٹھہر ٹھہر کر قرآن پڑھنا،پھراس میں غوروفکر کرنا،پھر سجدہ اور دعا کرنا،پھر اللہ سے ڈرنا اور رونا.\nrefl\nوَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ\nیعنی وقفہ وقفہ سے تاکہ اس کے معانی میں غوروفکر کریں اور اس کے مختلف علوم وفنون نکال سکیں۔(السعدی: ۴۶۸)\nغوروفکر کرنے والے کے لئے قرآن پڑھنے کا بہتر طریقہ کیا ہے؟\nقُلۡ ءَامِنُواْ بِهِۦٓ أَوۡ لَا تُؤۡمِنُوٓاْۚ إِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مِن قَبۡلِهِۦٓ إِذَا يُتۡلَىٰ عَلَيۡهِمۡ يَخِرُّونَۤ لِلۡأَذۡقَانِۤ سُجَّدٗاۤ ١٠٧\n(قل آمنوا به أو لا تؤمنوا)ایمان لاؤ یا نہ لاؤ۔یہ دراصل ان کی حقارت اور ان سے بے توجہی کی طرف اشارہ ہے۔گویا اللہ تعالیٰ فرمارہا ہے کہ:تمہارے لئے برابر ہے ایمان لاؤ یا نہ لاؤ کیونکہ تم حجت نہیں ہوبلکہ حجت تو وہ اہل ِعلم ہیں جو تم سے پہلے تھے اور وہ اہل ِکتاب کے مومنین ہیں (إن الذين أُوتوا العلم من قبله) یعنی اہل ِکتاب کے مومن لوگ۔اور کہا گیا کہ اس سے مراد وہ لوگ ہیں جو نبی صلی اللہ علیہ وسلم کی بعثت سے پہلے دین ِحنیف پر قائم تھے۔(ابن جزی: ۱؍۴۹۹)\nاس آیت میں اہل ِعلم کے مرتبہ کی بلندی کا ذکر ہے۔اس کی وضاحت کیجئے.\nإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مِن قَبۡلِهِۦٓ إِذَا يُتۡلَىٰ عَلَيۡهِمۡ يَخِرُّونَۤ لِلۡأَذۡقَانِۤ سُجَّدٗاۤ ١٠٧ وَيَقُولُونَ سُبۡحَٰنَ رَبِّنَآ إِن كَانَ وَعۡدُ رَبِّنَا لَمَفۡعُولٗا ١٠٨ وَيَخِرُّونَ لِلۡأَذۡقَانِ يَبۡكُونَ وَيَزِيدُهُمۡ خُشُوعٗا۩ ١٠٩\n(ويخرون للأذقان يبكون)یہ ان کی صفت میں مبالغہ اور ان کے حق میں تعریف ہے۔اور یہ حق ہر اس شخص کو حاصل ہے جو علم سے آگاہ ہو اور اسے حاصل کیا ہو کہ وہ اس مقام تک دوڑکر آئے اور قرآن سنتے وقت خشوع وخضوع اختیار کرے۔سنن دارمی میں ابراہیم تیمی رحمہ اللہ سے روایت ہے انہوں نے کہا:جسے علم سے نوازاگیا اور اس نے اسے رلایا نہیں تو وہ اس لائق نہیں کہ اسے علم عطاکیا جائے کیونکہ اللہ تعالیٰ نے علماء کی صفت بیان کی ہے۔یہ کہہ کر انہوں نے اسی آیت کی تلاوت کی۔(القرطبی: ۱۳؍۱۸۹)\nقرآن سنتے وقت اہل ِعلم کی کیا حالت ہونی چاہئے۔اسے واضح کیجئے۔؟\nوَيَخِرُّونَ لِلۡأَذۡقَانِ يَبۡكُونَ وَيَزِيدُهُمۡ خُشُوعٗا۩ ١٠٩\nٹھوڑی کے بل گرنا،ایسی مقصود عبادت ہے جسے اللہ پسند کرتا ہے۔یہاں ٹھوڑی کے بل گرنے سے مراد زمین سے ٹھوڑی کولگانا نہیں ہے جیسے پیشانی کو لگایا جاتا ہے بلکہ ٹھوڑی کے بل گرنا یہ رکوع کی ابتدا ہے اور سجدہ اس کی انتہا ہے۔(ابن تیمیہ: ۴؍۲۴۹)\nٹھوڑی کے بل گرنے کی وہ کون سی صورتیں ہیں جنہیں اللہ پسند کرتا ہے؟\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَٰبَ\nاللہ نے اپنی ذات کی خود تعریف کی ہے جس میں بندوں کی اس بات کی جانب رہنمائی بھی ہے کہ وہ ان کی طرف رسولوں کو بھیجنے اور ان پر کتابوں کے اتارنے پر اس کی تعریف کریں۔(السعدی: ۴۶۹)\nاللہ تعالیٰ نے اپنی تعریف خود کی ہے اسے جان کر ایک مسلمان کیا عملی فائدہ حاصل کرسکتاہے؟\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَٰبَ وَلَمۡ يَجۡعَل لَّهُۥ عِوَجَاۜ ١\nرسول اللہ صلی اللہ علیہ وسلم کا خاص طور سے ذکر کیا گیا کیونکہ آپ صلی اللہ علیہ وسلم پر قرآن کا اتارنا بالخصوص آپ پر اور بالعموم سارے لوگوں پر اللہ کی طرف سے ایک نعمت ہے۔ (البغوی: ۳؍۵)\nنبی صلی اللہ علیہ وسلم کا خاص طور سے کیوں ذکر کیا گیا ہے؟\nقَيِّمٗا لِّيُنذِرَ بَأۡسٗا شَدِيدٗا مِّن لَّدُنۡهُ وَيُبَشِّرَ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرًا حَسَنٗا ٢ مَّٰكِثِينَ فِيهِ أَبَدٗا ٣\nیہ قرآن ہر اس عمل ِصالح کو شامل ہے جو دلوں او ر روحوں کو خوش کرنے والی چیزوں تک پہنچانے والا ہے۔(السعدی؍۴۷۰)\nمومن کے نزدیک خوش ہونے کا منبع کیا ہے؟\nwords\nفَرَقنَاهُہم نے اس کو بيان کيا/ ہدايت و گمراہي کي تفصيل بيان کي.\nمُكثٍآہستہ /ٹھہر ٹھہر کر.\nيَخِرُّونَ لِلأَذقَانِٹھوڑيوں کے بل سجدہ کرتے ہيں.\nوَلا تُخَافِتنہ ہي پست کرو تم.\nعِوَجًاٹيڑھا پن / حق سے ميلان.\nمِن لَدُنهُاس کي طرف سے."],[294,"§الكهف\ndeeds\nیہ دعا مانگئے: “اَللّٰهُمَّ يَا مُقَلِّبَ الْقُلُوْبِ! ثَبِّتْ قَلْبِي عَلٰى دِيْنِكَ”۔اے اللہ!اے دلوں کے پھیرنے والے! میرے دل کو اپنے دین پر جمائے رکھ.\nآج بکثرت یہ دعا پڑھئے.\nآج ہی ایسے اچھے دوست بنانے کی منصوبہ بندی کرلیجئے جو عبادت اور دین پر ثابت قدمی میں آپ کے معاون بنیں.\nguid\nلوگوں کے ایمان لانے کی چاہت میں نبی صلی اللہ علیہ وسلم کی شفقت ملاحظہ کیجئے کہ اس چاہت میں آپ کی جان پر بن آئی تھی.\nہوشیار رہئے! بیشک نعمتیں اور دنیوی لذتیں اللہ سبحانہ وتعالیٰ کی جانب سے آزمائش ہیں اس طور پر کہ آپ ان سے اچھے کاموں میں بھی مدد لے سکتے ہیں اور گناہوں میں بھی.\nاچھے ساتھی ہدایت اور دین پر ثابت قدم رہنے کے اسباب میں سے ہیں.\nrefl\nفَلَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ عَلَىٰٓ ءَاثَٰرِهِمۡ إِن لَّمۡ يُؤۡمِنُواْ بِهَٰذَا ٱلۡحَدِيثِ أَسَفًا ٦\nاس آیت کریمہ او ر اس قسم کی دیگر آیات میں عبرت ہے۔مخلوق کو اللہ تعالیٰ کی طرف دعوت دینے پر مامور شخص پر دعوت وتبلیغ کے ان تمام اسباب کے حصول میں کوشاں رہنا جو ہدایت کی منزل تک پہنچاتے ہیں،امکان بھر گمراہی کے راستوں کو مسدود کرنا اور اس بارے میں اللہ پر توکل کرنا فرض ہے۔ پس اگر مدعو ہدایت پر آجائیں تو بہتر ہے ورنہ داعی کو ان پر افسوس میں گھلنا نہیں چاہئے کیونکہ یہ چیز نفس کو کمزور او ر قوائے بدن کو منہدم کردیتی ہے۔اس میں کوئی فائدہ نہیں بلکہ ایسا کرنے سے وہ مقصد فوت ہوجائیگاجس پر اسے متعین کیا گیا ہے۔دعوت وتبلیغ اور اس راہ میں کوشش کے سوا دوسری چیزیں آپ کی قدرت سے باہر ہیں۔ (السعدی؍۴۷۰)\nآیت میں بہت بڑا دعوتی فائدہ ہے۔اسے واضح کیجئے.\nإِنَّا جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِينَةٗ لَّهَا لِنَبۡلُوَهُمۡ أَيُّهُمۡ أَحۡسَنُ عَمَلٗا ٧\n(إنا جعلنا ما على الأرض زينة لها) ہم نے زمین پر موجود چیزوں کو بطور زینت بنایا ہے یعنی جو زینت اختیار کرنے کے لائق ہو ں جیسے لباس، کھاناپینا،درخت اور نہریں وغیرہ (لنبلوهم أيهم أحسن عملًا) یعنی تاکہ ہم انہیں آزمائیں کہ دنیا کی زیب وزینت اختیار کرنے میں کون زہد وورع سے کام لیتا ہے۔(ابن جزی: ۱؍۵۰۲)\nاللہ تعالیٰ نے زمین کو ایک بڑی حکمت کے تحت زینت کی بہت ساری چیزوں سے مزین کررکھا ہے۔وہ کیا ہیں؟\nأَمۡ حَسِبۡتَ أَنَّ أَصۡحَٰبَ ٱلۡكَهۡفِ وَٱلرَّقِيمِ كَانُواْ مِنۡ ءَايَٰتِنَا عَجَبًا ٩ إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا ١٠\nجو لوگ عجیب قصوں کے امور میں مشغول ہونے کے لئے سوال کرتے ہیں،اس میں انہیں اسی بات کی طرف توجہ دلائی گئی ہے کہ ان کے لئے بہتر یہ ہے کہ وہ ان قصوں سے عبرت حاصل کریں نیزان کے اسباب ونتائج سے نصیحت پکڑیں اسی لئے اصحابِ کہف کے احوال کو اللہ تعالیٰ نے اپنے اس فرمان سے شروع کیا ہے: (إذ أوى الفتية إلى الكهف فقالوا ربنا آتنا من لدنك رحمة وهيِّئ لنا من أمرنا رشدًا) (ابن عاشور: ۱۵؍۲۵۹)\nقصوں کے تعلق سے مناسب یہ ہے کہ ان کے اندر پائی جانے والی عبرتوں اور نصیحتوں پر عمل کیا جائے نہ کہ ان کے عجائبات میں مشغول ہوا جائے۔ اصحاب ِکہف کے واقعہ کی روشنی میں اسے دلیل سے واضح کریں.\nإِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا ١٠\nاس آیت میں اس بات کی صراحت ہے کہ فتنوں کے خوف اور سخت آزمائش سے بچنے کے لئے دین کی خاطر گھربار،اہل وعیال،رشتہ داراور دوستوں کو چھوڑکر ہجرت کی جاسکتی ہے۔نبی صلی اللہ علیہ وسلم اور آپ کے صحابہ نے دین کی خاطر اپنے وطن،گھربار،اہل وعیال اور رشتہ داروں کو چھوڑدیا تھاتاکہ کافرو ں کے فتنوں سے نجات پاسکیں۔ (القرطبی: ۱۳؍۲۱۶)\nاگر مومن کو اپنے دین کا خوف ہو تو کیا وہ اپنا وطن چھوڑدے یا دین کو خطرے میں ڈال کر وہیں باقی رہے؟\nإِنَّهُمۡ فِتۡيَةٌ ءَامَنُواْ بِرَبِّهِمۡ وَزِدۡنَٰهُمۡ هُدٗى ١٣\nاللہ تعالیٰ نے ذکر کیا کہ وہ نوجوان تھے جو حق کو قبول کرنے اور سیدھے راستہ پر آنے میں ان بوڑھوں سے زیادہ تیز ہوتے ہیں جو دین ِباطل میں منہمک اور سرکشی میں پڑے ہوتے ہیں۔یہی وجہ ہے کہ اللہ اور رسول اللہ صلی اللہ علیہ وسلم کی بات ماننے والے اکثر نوجوان تھے جبکہ قریش کے اکثر بوڑھے اپنے پرانے دین پر قائم رہے اور ان میں سے بہت کم ہی اسلام لائے۔(ابن کثیر: ۳؍۷۲)\nدعوت الی اللہ کا بار سنبھالنے کے لئے کس عمر کے لوگ زیادہ مناسب ہوتے ہیں؟\nوَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ\nیعنی صبر او ر ثبات قدمی کے ذریعہ ان کے دلوں کو مضبوط کردیا اور نور ِایمان کے ذریعہ انہیں طاقت بخشی یہاں تک کہ انہوں نے اپنے گھر بار،مقام ومرتبہ اور عیش وآسائش کی زندگی کو ترک کرکے اپنے دین کی خاطر غار میں پناہ لے لی۔(البغوی: ۳؍۱۷)\nاللہ تعالیٰ نے اصحاب ِکہف کے دلوں کو کیسے مضبوط کیا؟\nوَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ\nدلوں کو مضبوط کرنا ذلت و رسوائی کے برخلاف ہے، ذلت و رسوائی کہتے ہی ہیں توفیق سے محرومی کو کہ جس کی بنیاد پر ہر بندہ اپنے رب کے ذکر سے غافل ہوکر اپنے خواہشات کی پیروی کر بیٹھتا ہے اور اس کا معاملہ حد سے گزرجاتا ہے۔ جبکہ دل کو مضبوط کرنے کا مطلب اسے توفیق الہٰی سے باندھ دینا ہے تاکہ وہ اپنے رب کی ذکر میں مشغول ہوجائے، اس کی رضاجوئی کی اتباع کرے اور صرف اسی کا ہوکر رہ جائے۔(ابن قیم: ۲؍۱۵۷)\nمذکورہ آیت کی روشنی میں دل کی مضبوطی اور رسوائی کے درمیان فرق کو واضح کیجئے؟\nwords\nبَاخِعٌہلاک کرنے والا.\nأَسَفًاغم و افسوس سے.\nوَالرَّقِيمِوہ تختي جس پر ان کے نام تحرير تھے.\nأَمَدًامدت /انتہاء.\nشَطَطًاحق سے دور / ظلم."],[295,"§الكهف\ndeeds\nاپنے کھانے کے مینو میں صرف پاکیزہ اور حلال رزق ہی شامل کریں۔حرام اور مشتبہ چیزوں سے بچیں۔بیشک یہ آپ کے دل کی درستگی،عقل کی تقویت اور دعاؤں کی قبولیت کا اہم ذریعہ ہے.\nاللہ کے علاوہ ہدایت کے حصول کا کوئی اور راستہ نہیں ہے لہذا اسی سے مانگئے جو اس کا مالک ہے نیز گمراہی او ر بے راہ روی سے اس کی پناہ مانگئے.\nدشمن سے مڈ بھیڑ کی تمنا نہ رکھئے اور اپنے دین ودنیا میں اللہ سے عافیت وخیر کا سوال کرتے رہئے.\nguid\nاللہ نے اپنے نیک بندوں کی حالت نیند میں حفاظت کی ہے تو کیا ان کے جاگتے میں ان کی حفاظت نہیں کریگا؟\nپاکیزہ غذا کے بہت سے فوائد ہیں،بیشک وہ ہدایت کا ذریعہ،دعا کی قبولیت اور بہت سی بیماریوں سے بچاؤ کا سبب ہے.\nمومن جس قدر کافروں کی دشمنی سے خبردار رہے گا اسی قدر ان کے شر سے محفوظ رہے گا.\nrefl\nوَإِذِ ٱعۡتَزَلۡتُمُوهُمۡ وَمَا يَعۡبُدُونَ إِلَّا ٱللَّهَ\nایسا کہا جاتا ہے کہ ان نوجوانوں نے جب اپنے بادشاہ کو اللہ پر ایمان لانے کی دعوت دی تو اس نے انکار کردیا اور انہیں دھمکی بھی دی۔البتہ انہیں مہلت دے دی تاکہ یہ اپنے نئے دین کے بارے میں غور وفکر کریں لیکن وہ اس مہلت میں غوروفکر کرنے کے بعد اس نتیجہ پر پہنچے کہ آزمائش میں پڑنے سے بہتر ہے کہ یہاں سے راہ فرار اختیار کرلی جائے۔چنانچہ ایسی ہی صورت حال میں لوگوں سے دور ہوجانا مشروع ہے البتہ دوسری حالتوں میں سماج سے دوری بالکل جائز نہیں ہے کیونکہ ایسی حالت میں آدمی سےجمعہ اور جماعت فوت ہوجائے گا۔(ابن کثیر: ۳؍۷۳)\nایک مسلمان کے لئے دین کی خاطر لوگوں سے دور چلے جانا کب جائز ہے؟\nوَتَرَى ٱلشَّمۡسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهۡفِهِمۡ ذَاتَ ٱلۡيَمِينِ وَإِذَا غَرَبَت تَّقۡرِضُهُمۡ ذَاتَ ٱلشِّمَالِ وَهُمۡ فِي فَجۡوَةٖ مِّنۡهُۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِۗ\nآیت کا مفہوم یہ ہے کہ طلو ع وغروب کے وقت سورج کی دھوپ ان کے بدن کو نہیں چھوتی تھی کہ کہیں اس کی گرمی سے ان کے بدن نہ جلنے لگیں۔ اسی لئے کہا گیا ہے کہ یہ ان کے حق میں کرامت ہے۔ (ابن جزی: ۱؍۵۰۴)\nاللہ تعالیٰ نے اصحاب ِکہف کی حفاظت کس طرح فرمائی؟\nمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ\nیعنی ہدایت صرف اللہ کے ہی ہاتھ میں ہے،وہی ہدایت دینے والا ہے اور وہی سعادت ِدارین کی طرف رہنمائی کرنے والا ہے۔ (السعدی؍۴۷۲)\nاگر آپ کو ہدایت چاہئے تو کس سے طلب کریں گے؟\nوَنُقَلِّبُهُمۡ ذَاتَ ٱلۡيَمِينِ وَذَاتَ ٱلشِّمَالِۖ\nیہ انتظام بھی اللہ تعالیٰ کی طرف سے ان کے جسموں کی حفاظت کے لئے تھا کیونکہ یہ زمین کی خاصیت ہے کہ جو چیز اس کے ساتھ پیوست رہتی ہے یہ اسے کھاجاتی ہے۔یہ اللہ تعالیٰ کی قدرت تھی کہ وہ ان کو کبھی دائیں پہلو اور کبھی بائیں پہلو پر پلٹتے رہتا تھا تاکہ زمین ان کے جسموں کو خراب نہ کرے۔ اور اللہ تعالیٰ تو اس بات پر بھی قادر ہے کہ وہ ان کے پہلوؤں کو ادل بدل کئے بغیر بھی ان کے جسموں کی حفاظت کرتا مگر اللہ تعالیٰ حکیم ہے،اس نے چاہا کہ وہ تکوینی قوانین میں اپنی سنت کو جاری رکھے اور اسباب کو ان کے مسبّبات سے جوڑدے۔(السعدی؍۴۷۲)\nاللہ تعالیٰ اصحاب ِکہف کے پہلو بدلے بغیر بھی ان کی حفاظت کرنے پر قادر تھا۔ پھر اس نے ایسا کیوں نہ کیا؟\nوَكَلۡبُهُم بَٰسِطٞ ذِرَاعَيۡهِ بِٱلۡوَصِيدِۚ\nابن عطیہ رحمہ اللہ نے فرمایا: جب کتے کا یہ حال ہے کہ اس نے نیک لوگوں کی صحبت اختیار کرکے بلند مرتبہ پالیا یہاں تک کہ اللہ تعالیٰ نے اپنے کلام ِپاک میں اس کا ذکر فرمادیا۔پھر ان موحد مومنوں کے بارے میں آپ کا کیا گمان ہے جو اولیاء وصالحین سے محبت کرتے ہیں۔ (القرطبی: ۳۱؍۲۳۲)\nقرآن میں اس واقعہ میں کتے کے ذکر سے ہم کیا سبق سیکھتے ہیں؟\nقَالُواْ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ\nجسے کسی چیز کے بارے میں شبہ ہوجائے اس میں ادب کا پہلو یہی ہے کہ اس علم کو اللہ کے حوالے کردے اور اپنی حد سے تجاوز نہ کرے۔ (السعدی؍۴۷۳)\nاگر کسی ایسی چیز کے بارے میں آپ سے پوچھا جائے جسے آپ نہ جانتے ہوں تو اس بارے میں شرعی ادب کیا ہے؟\nفَلۡيَنظُرۡ أَيُّهَآ أَزۡكَىٰ طَعَامٗا فَلۡيَأۡتِكُم بِرِزۡقٖ مِّنۡهُ\nاچھی چیزیں اور لذیذ کھانے کھانا جائز ہے جبکہ ان میں اسراف نہ ہو جو کہ ممنوع ہے خاص طور سے جبکہ انسان کو اس کے سوا کوئی او ر کھانا موافق نہ آتا ہو۔ (السعدی؍۴۷۳)\nکیا انسان اس بات کا پابندہے کہ وہ پاکیزہ اور اچھے کھانوں سے دور رہے؟\nwords\nمِرفَقًااسباب زندگي جن سے تم فائدہ اٹھاتے ہو.\nتَزَاوَرُتم ميلان رکھتے ہو.\nتَقرِضُهُمان سے تجاوز کرتي ہے.\nفَجوَةٍکھلي جگہ / غار."],[296,"§الكهف\ndeeds\nآج بکثرت اللہ کا ذکر کیجئے.\nآج سے ہی عادت بنالیجئے کہ مستقبل کے بارے میں کوئی بھی بات کریں تو ان شاء اللہ کہیں گے.\nقرآن کریم کی کوئی سورت پڑھئے.\nguid\nنیکی کے کاموں میں صرف جوش اور جذبہ سے کام نہیں چلتا بلکہ اس میں شریعت کی پاسداری ضروری ہے جیسا کہ قبروں پر مسجدیں بنانا حرام ہے.\nاُسی مسئلہ میں بحث کیجئے جس کا آپ کو علم ہو.\nدینی معاملات میں کوئی فتویٰ پوچھنا ہو تو اس عالم سے پوچھئے جو علم اور عبادت میں زیادہ بہتر ہو.\nrefl\nوَكَذَٰلِكَ أَعۡثَرۡنَا عَلَيۡهِمۡ لِيَعۡلَمُوٓاْ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَأَنَّ ٱلسَّاعَةَ لَا رَيۡبَ فِيهَآ\nاس واقعہ میں اس بات کی دلیل ہے کہ جو دین کی خاطر فتنوں سے دور رہے گا تو اللہ تعالیٰ اس کی حفاظت کریگا اور جو عافیت کا خواہش مند ہوگا تو اللہ اسے ضرور عافیت دیگا اور جو اللہ کی پناہ میں آئیگا تو اللہ اسے ضرور پناہ دیگا اور اسے دوسروں کے لئے ہدایت کا ذریعہ بنائیگا اور جو اللہ کی رضا کی خاطر اس کے راستہ میں ذلت برداشت کریگا تو یقینا اس کا انجام ایسی عظیم عزت ومرتبہ کی صورت میں ہوگا جس کا اسے گمان بھی نہ ہوگا۔ (السعدی: ۴۷۳)\nاصحاب کہف کے واقعہ سے تین مختصرفوائد ذکر کیجئے.\nفَقَالُواْ ٱبۡنُواْ عَلَيۡهِم بُنۡيَٰنٗاۖ رَّبُّهُمۡ أَعۡلَمُ بِهِمۡۚ قَالَ ٱلَّذِينَ غَلَبُواْ عَلَىٰٓ أَمۡرِهِمۡ لَنَتَّخِذَنَّ عَلَيۡهِم مَّسۡجِدٗا ٢١\nمسجدوں پر قبریں بنانا اور ان میں نماز پڑھنا منع ہے کیونکہ یہ عمل صاحب ِقبر کی عبادت تک پہنچا سکتا ہے،یا یہ ان لوگوں کے عمل جیسا ہے جو اپنی قوم کے نیک لوگوں کی عبادت کرتے تھے۔(ابن عاشور: ۱۵؍۲۹۰)\nہمیں قبروں پر مساجد بنانے سے کیوں منع کردیا گیا ہے؟\nقُل رَّبِّيٓ أَعۡلَمُ بِعِدَّتِهِم\nاس آیت میں اس بات کی طرف رہنمائی ہے کہ ایسے موقعوں پر سب سے بہتر یہ ہے کہ علم کو اللہ تعالیٰ کے حوالے کردیا جائے کیونکہ بغیر علم کے اس طرح کے مسئلوں کے پیچھے پڑنے کی ضرورت نہیں ہے۔اس لئے اگر ہمیں کسی چیز کاعلم ہو تو اسے کہنا چاہئے ورنہ توقف اختیار کرکے خاموش رہنا چاہئے۔ (ابن کثیر: ۳؍۷۷)\nبعض علمی مسائل میں الجھن اور پریشانی کے وقت ایک طالب علم کے لئے سب سے بہتر طریقہ کیا ہے؟\nوَلَا تَسۡتَفۡتِ فِيهِم مِّنۡهُمۡ أَحَدٗا ٢٢\nاس آیت کریمہ سے پتہ چلتاہے کہ جو فتویٰ دینے کی صلاحیت نہیں رکھتا اس سے فتویٰ نہ پوچھا جائے خواہ اس کی وجہ یہ ہو کہ جس امر کے بارے میں فتویٰ پوچھاجارہا ہے وہ اس میں کوتاہ علم ہے یا اس کی وجہ یہ ہو کہ وہ بولتے وقت اس بات کی پرواہ نہیں کرتا کہ وہ کیا بول رہا ہے نیز وہ اس تقویٰ اور پرہیزگاری سے بھی خالی ہے جو اسے لایعنی کلام سے روکے۔ آیت کریمہ میں اس بات کی بھی دلیل ہے کہ انسان کو بسا اوقات کسی معاملہ میں فتویٰ طلب کرنے سے روک دیا جاتا ہے مگر کسی دوسرے معاملہ میں اجازت ہوتی ہے چنانچہ وہ ایسے شخص سے فتویٰ طلب کرے جو فتویٰ دینے کا اہل ہو اس لئے کہ اللہ تعالیٰ نے فتویٰ پوچھنے سے علی الاطلاق منع نہیں کیا ہے۔ اللہ تبارک وتعالیٰ نے صرف اصحاب ِکہف کے قصہ میں اور اسی قسم کے دیگر واقعات میں فتویٰ پوچھنے سے روکا ہے۔(السعدی: ۴۷۴)\nآیت سے معلوم ہونے والے بعض مسائل اور فتویٰ پوچھنے کے تعلق سے کچھ ذکر کیجئے.\nوَلَا تَقُولَنَّ لِشَاْيۡءٍ إِنِّي فَاعِلٞ ذَٰلِكَ غَدًا ٢٣ إِلَّا أَن يَشَآءَ ٱللَّهُۚ\nیعنی اگر کل کچھ کرنے کا ارادہ ہو تو یہ نہ کہیں کہ کل کروں گا جب تک ان شاء اللہ نہ کہہ لیں۔(البغوی: ۳؍۲۳)\nمستقبل میں اگر کوئی کچھ کرنا چاہتا ہو تو اس پر کیا کہنا واجب ہوتا ہے۔اس تعلق سے قرآنی ادب واضح کیجئے.\nوَٱذۡكُر رَّبَّكَ إِذَا نَسِيتَ\nاگر کوئی گفتگو کرتے وقت اگر کچھ بھول جائے تو اسے اللہ تعالیٰ کا ذکر کرنے کی تعلیم دی گئی ہے کیونکہ خطا ونسیان کا منبع ومصدر شیطان ہے اور شیطان کو ذکرالٰہی ہی بھگا سکتا ہے چنانچہ جب شیطان چلا جائیگا تو نسیان وسہو بھی چلا جائیگا۔پس اللہ کا ذکر یاددہانی کا سبب ہے۔(ابن کثیر: ۳؍۷۸)\nاللہ کا ذکر کرنے سے نسیان وسہو کے جانے کا کیا تعلق ہے؟\nمَا لَهُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا يُشۡرِكُ فِي حُكۡمِهِۦٓ أَحَدٗا ٢٦\nولی اور دوست وہ ہے کہ آپ کے اور اس کے درمیان کوئی ایسا سبب ہو جس کی وجہ سے وہ آپ سے اور آپ اس سے لگاؤ رکھتے ہوں۔چنانچہ ایمان ایک سبب ہے جس کی وجہ سے مومنین اطاعت وفرمانبرداری کے ذریعہ اپنے رب سے لگاؤ رکھتے ہیں اور ثواب،غلبہ اور مدد کے ذریعہ ان کے ساتھ ان کے رب کابھی لگاؤ ہوتا ہے۔\nاللہ کا مومنوں کے ساتھ اور مومنو ں کا اللہ کے ساتھ لگاؤ کیسا ہوتا ہے؟\nwords\nأَعثَرنَا عَلَيهِمہم نے ان کے بارے ميں اس زمانے والوں کو آگاہ کيا.\nلا رَيبَشک نہيں.\nغَلَبُوا عَلَى أَمرِهِمان ميں سے صاحب نفوذ.\nرَجمًا بِالغَيبِظن کي بنا پر بلا علم کي بات.\nفَلاَ تُمَارِ فِيهِمان کي گنتي ميں جھگڑا نہ کريں.\nإلَّا مِرَاءً ظَاهِرًامگر ظاہر جھگڑا ؛ جس ميں زيادہ گہرائي نہ ہو/ بس آپ ان کو وحي بتاديں.\nمُلتَحَدًاٹھکانہ جہاں پناہ لي جاتي ہو."],[297,"§الكهف\ndeeds\nکسی نیک جماعت کے ساتھ دعوت کے کاموں میں شرکت کیجئے.\nنیک انسان کو تلاش کرکے اس سے دوستی کیجئے نیز اس سے دوستی برقرار رکھئے اور اسے اللہ کی عبادت سمجھئے.\nاللہ نے آپ کو جن نعمتوں سے نوازا ہے ان کے سبب گھمنڈ میں پڑجانے سے اللہ کی پناہ مانگئے اور اللہ سے دعا کیجئے کہ وہ نعمتیں آپ کے لئے عبادت میں مددگار ہوں.\nguid\nصبح وشام کے اذکار کے ساتھ کوئی ورد خاص کرلیجئے جسے آپ ہمیشہ پڑھاکریں.\nنیک لوگوں کے ساتھ رہئے۔انہی کے ساتھ رہنے اور ان سے ملنے جلنے کی پابندی کیجئے گرچہ وہ مسکین ہوں اور خبردار رہئے کہیں دنیا کی رنگینی آپ کو ان سے دور نہ کردے.\nبڑی سزاؤں میں سے یہ بھی ہے کہ آپ کو کچھ گناہوں کے سبب یوں سزادی جائے کہ آپ کے دل کو اللہ کی یاد سے غافل کردیا جائے.\nrefl\nوَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ وَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ تُرِيدُ زِينَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمۡرُهُۥ فُرُطٗا ٢٨\n(واصبر نفسك) یعنی اپنے نفس کو صبر کے ساتھ روکے رکھئے (مع الذين يدعون ربهم) ان سے مسکین مسلمان مراد ہیں۔ جیسے بلال،خباب اور صہیب رضی اللہ عنہم وغیرہ۔کفار نے رسول اللہ صلی اللہ علیہ وسلم سے انہی کے بارے میں کہا تھا کہ انہیں اپنے پاس سے دور ہٹادیجئے پھر ہم آپ کے پاس بیٹھیں گے۔(ابن جزی: ۱؍۵۰۷)\nداعی کو دعوت کے میدان میں مختلف طبقات کا سامنا کرنا ہوتا ہے چنانچہ ان کے ساتھ قرآنی منہج کی روشنی میں کیسے پیش آئیں گے؟\nوَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ\nآیت سے صبح وشام ذکر واذکار اور دعاوعبادت کے استحباب کا پتہ چلتا ہے کیونکہ اللہ تعالیٰ نے ان کے اس عمل کی تعریف کی ہے اور اللہ تعالیٰ جس بھی عمل کی تعریف کردے وہ اس کے مستحب ہونے کی دلیل ہے۔ اور اللہ جس چیز کو پسند کرتا ہے،اس کا حکم بھی دیتا ہے اور اس کی رغبت بھی دلاتا ہے۔ (السعدی؍۴۷۵)\nیہ آیت صبح وشام ذکر واذکار کی مشروعیت پر کیسے دلالت کرتی ہے؟\nوَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ تُرِيدُ زِينَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ\n(تريد زينة الحياة الدنيا) یعنی دنیاوی زندگی کی رونق کی تلاش ہے کیونکہ یہ چیز نقصان دہ ہے،اس میں کوئی فائدہ نہیں ہے۔یہ تمام دینی مصلحتوں کے یکسر خلاف ہے کیونکہ یہ دنیا سے دل لگانے کا سبب بنتی ہے جس سے دل میں اندیشے جاگزیں ہوجاتے ہیں اور دل سے آخرت کی چاہت مٹنے لگتی ہے کیونکہ دنیا کی زیب وزینت دیکھنے والے کو بہت خوش کن نظر آتی ہے اور عقل پر جادوکردیتی ہے جس سے دل اللہ کے ذکر سے غافل ہوکر لذتوں و شہوتوں میں مگن ہوجاتا ہے پھر وہ اپنے وقت کو ضائع کرکے اپنے معاملہ میں کوتاہی کا شکار ہوجاتا ہے۔ (السعدی؍۴۷۵)\nآخرت کے بدلہ میں دنیا سے محبت کا کیا نقصان ہے؟\nوَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمۡرُهُۥ فُرُطٗا ٢٨\nیہ آیت کریمہ اس بات پر دلالت کرتی ہے کہ وہی شخص اطاعت کے لائق او ر لوگوں کا امام بننے کے قابل ہے جس کا دل محبت ِالٰہی سے لبریز ہو اور اس کی زبان پر محبت الٰہی کا فیضان ہو،وہ اللہ تعالیٰ کا ذکر کرتاہو،اپنے رب کی رضا کی پیروی کرتا ہو اور اسے اپنی خواہشات پر مقدم رکھتاہو۔پس اس طرح وہ اپنے وقت کی حفاظت کریگا،اس کے تمام احوال درست اور تمام افعال ٹھیک ہوجائیں گے۔وہ لوگوں کو اس چیز کی طرف دعوت دیگا جس کے ذریعہ سے اللہ تعالیٰ نے اس پر احسان کیا ہے۔پس یہ شخص اس بات کا مستحق ہے کہ اس کی اتباع کی جائے اور اس کو امام بنایا جائے۔(السعدی؍۴۷۵)\nانسان کے لئے ضروری ہے کہ وہ بعض دینی اور دنیوی معاملات میں دوسرے کی تقلید اور پیروی کرے۔تو ایسی صورت میں ہمیں کس کی پیروی کرنا چاہئے اور کس سے دور رہنا چاہئے؟\nوَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَآءَ فَلۡيُؤۡمِن وَمَن شَآءَ فَلۡيَكۡفُرۡۚ\nاللہ تعالیٰ جسے چاہتا ہے حق سے نوازتا ہے گرچہ وہ کمزور ہی کیوں نہ ہو اور جسے چاہتا ہے اس سے محروم کردیتاہے گرچہ وہ طاقتور ومالدار کیوں نہ ہو۔تمہاری خواہش پر میں مومنوں کو نہیں بھگاسکتا،تم چاہو تو ایمان لاؤ اور چاہو تو کفر کرو۔ (القرطبی: ۱۳؍۲۶۰)\nآخرت کی نعمتوں کا ملنا اور ان سے محرومی کیا انسان کی مالداری اور فقیری پر منحصر ہے؟\nوَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَآءَ فَلۡيُؤۡمِن وَمَن شَآءَ فَلۡيَكۡفُرۡۚ\nکفر پر ایمان کو مقدم کیا گیا کیونکہ ان کا ایمان ہی مطلوب ہے۔(ابن عاشور: ۱۵؍۳۰۷)\nاس آیت میں کفر پر ایمان کو مقدم کیوں کیا گیا؟\nوَكَانَ لَهُۥ ثَمَرٞ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكۡثَرُ مِنكَ مَالٗا وَأَعَزُّ نَفَرٗا ٣٤\nامام قتادہ رحمہ اللہ نے کہا:اللہ کی قسم! ایک فاسق وفاجر شخص کی تمنا یہی ہوتی ہے کہ اسے زیادہ سے زیادہ دولت اور نفری عزت مل جائے۔(ابن کثیر: ۳؍۸۱)\nکافر کی سب سے بڑی تمنا کیا ہوتی ہے او ر ایک مومن کو اس سے کیا سبق ملتا ہے؟\nwords\nفُرُطًاہلاکت ميں پڑا/ ضائع ہونے والا.\nسُرَادِقُهَااس کي ديواريں.\nكَالمُهلِپگھلے ہوئے تانبے کي طرح.\nسُندُسٍباريک ريشم.\nوَإِستَبرَقٍاور موٹا ريشم."],[298,"§الكهف\ndeeds\nآپ کے کوئی دوست جو اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی مخالفت کررہے ہوں تو انہیں نصیحت کیجئے۔بیشک دوستی نصیحت میں رکاوٹ نہیں بننی چاہئے.\nآپ نے زندگی میں جو کارنامے انجام دئیے ہوں یا کچھ بہترین کام کئے ہوں تو ان پر غور کیجئے او ران کا اعزاز اللہ کو دیتے ہوئے “مَا شَآءَ اللّٰهُ١ۙ لَا قُوَّةَ اِلَّابِاللّٰهِ” کہئے.\nاس نعمت پر اللہ سے معافی مانگئے جس کا اعزاز آپ نے اپنی ذات کو دیا ہواور اللہ کا فضل بھول بیٹھے ہوں۔بیشک شکر سے غافل رہنے والوں کو جلد ہی اس کی سزا بھگتنی پڑتی ہے.\nguid\nخبردار! اللہ کی چال(تدبیر) سے ہوشیار رہئے،دھوکے میں نہ رہئے.\nجسے اللہ تعالیٰ ذلیل کردے اس کی کوئی مدد نہیں کی جاسکتی.\nلوگوں کے ساتھ خاکساری سے پیش آئیے، فخر اورتکبرسے پرہیز کیجئے.\nrefl\nوَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٞ لِّنَفۡسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدٗا ٣٥\n(وهو ظالم لنفسه) وہ اپنے نفس پر ظلم کرنے والا تھا۔ یا تو کفر کرکے یا اپنے ساتھی کا مقابلہ کرکے جس میں کہ فخر،تکبر اور حقارت بھری ہوئی تھی۔ (ابن جزی: ۱؍۵۱۰)\nدوباغ والوں نے اپنے اوپر چار چیزوں سے ظلم کیا۔انہیں گنائیے؟\nوَلَئِن رُّدِدتُّ إِلَىٰ رَبِّي لَأَجِدَنَّ خَيۡرٗا مِّنۡهَا مُنقَلَبٗا ٣٦\nدنیا کی نعمت اور آخرت کی نعمت میں کون سا تلازم ہے کہ اس سے کوئی جاہل اپنی جہالت کی بناپر یہ سمجھ بیٹھے کہ جسے اس دنیا میں عطاکردیا گیا اسے آخرت میں بھی عطاکیا جائیگا حالانکہ اکثر یہی ہوتا ہے کہ اللہ تعالیٰ اپنے اولیاء اور خاص بندوں سے دنیا کو دور ہٹادیتا ہے اور اپنے ان دشمنوں پر اسے کشادہ کردیتا ہے جن کا آخرت میں کوئی حصہ نہیں ہوتا۔ (السعدی؍۴۷۷)\nدنیا کی نعمت اور آخرت کی نعمت میں کیا کوئی تلازم پایا جاتا ہے؟\nوَلَوۡلَآ إِذۡ دَخَلۡتَ جَنَّتَكَ قُلۡتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِۚ\nیعنی جو بھی مال ودولت تم نے اکٹھاکررکھی ہے وہ اللہ تعالیٰ کی قدرت اور اس کی طاقت ہی سے ملی ہے،نہ کہ تمہاری قدرت وطاقت سے۔اور اگر وہ چاہ لے تو اس میں برکت ختم کردے اور وہ تمہارے پاس جمع نہ ہوسکے۔(القرطبی: ۱۳؍۲۸۰)\nکیا انسان اپنی قدرت وطاقت سے کسی چیز کا مالک ہوسکتا ہے؟\nإِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالٗا وَوَلَدٗا ٣٩ فَعَسَىٰ رَبِّيٓ أَن يُؤۡتِيَنِ خَيۡرٗا مِّن جَنَّتِكَ\nاس شخص نے اس بات کی خبر دی کہ اس پر اللہ تعالیٰ کی نعمت،ایمان او ر اسلام کی شکل میں ہے گرچہ اس کے پاس مال ودولت اور اولاد کی کمی ہے اور ایمان واسلام کی نعمت ہی حقیقی نعمت ہے۔باقی نعمتیں زوال پذیر ہیں اور ساتھ ہی وہ باعث ِ عذاب بھی ہیں۔ (السعدی؍۴۷۷)\nوہ کو ن سی نعمت ہے جو ایک مسلمان پر سب سے زیادہ کامل،افضل اور پوری سمجھی جاتی ہے؟\nوَأُحِيطَ بِثَمَرِهِۦ فَأَصۡبَحَ يُقَلِّبُ كَفَّيۡهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا\nصرف کفر کی وجہ سے اسے عذاب نے نہیں گھیرلیا تھا کیونکہ اللہ بہت سارے کافروں کو پوری زندگی ڈھیل دے دے کر نعمتوں سے نوازتا رہتا ہے دراصل عذاب نے اسے اس کے ظلم کی بنیاد پر گھیرا تھا اور اس لئے کہ اس نے اپنے مال ودولت کو مسکین مومنوں کی حقارت کا ذریعہ بنارکھا تھا۔ (ابن عاشور: ۱۵؍۳۲۸)\nآیت میں ذکرکردہ کافر کو سزا دینے میں جلدی کیوں کی گئی حالانکہ اللہ تعالیٰ بہت سارے کافروں کو پوری زندگی نعمتوں سے نوازتا رہتا ہے؟\nوَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُشۡرِكۡ بِرَبِّيٓ أَحَدٗا ٤٢\nاللہ کی رحمت او ر اس کے لطف وکرم سے یہ بعید نہیں کہ وہ شخص جس کے باغ پر آفت نازل ہوئی تھی‘اس کی حالت سدھر گئی ہو،اس نے توبہ کرلی ہو اور ہدایت کی طرف لوٹ آیا ہو اور اس کی سرکشی اور تکبر ختم ہوگیا ہو۔اس کی دلیل یہ ہے کہ اس نے اپنے شرک پر ندامت کا اظہار کیا تھا۔اور یہ بھی بعید نہیں کہ اللہ تعالیٰ نے اس کی سرکشی کو دور کرکے اسے دنیا میں ہی سزا دے دی ہو کیونکہ اللہ تعالیٰ اپنے بندے کے ساتھ جب بھلائی چاہتا ہے تو اسے دنیا میں ہی سزا دے دیتا ہے۔(السعدی: ۴۷۸)\nدوباغ والے پرجو عذاب نازل ہوا تھا،ممکن ہے وہ اس کے لئے خیر ثابت ہوا ہو۔ اس کا سبب واضح کریں.\nوَٱضۡرِبۡ لَهُم مَّثَلَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ فَأَصۡبَحَ هَشِيمٗا تَذۡرُوهُ ٱلرِّيَٰحُۗ\nحکماء کا کہنا ہے کہ اللہ نے دنیا کو پانی سے تشبیہ دی کیونکہ پانی ایک حالت پر باقی نہیں رہتا اور اسی طرح دنیا بھی ہے کہ وہ بھی پانی کی طرح ختم ہوجائیگی اور یہ کہ ایسا کوئی نہیں ہے جو پانی میں داخل ہو اور بھیگے نا۔ اسی طرح دنیا ہے کہ کوئی بھی اس کے فتنہ اور مصیبت سے بچ نہیں سکتا۔ نیز یہ کہ پانی جب تک ایک مناسب مقدار میں رہے گا وہ نفع بخش اور سبزہ اگانے کے لائق ہوگا اور حد سے تجاوز کرنے پر نقصان دہ اور مہلک ہوجائیگا اسی طرح دنیا ہے کہ اس سے بقدر کفاف روزی نفع بخش ہے جبکہ زیادہ مقدار نقصان دہ ہے۔(القرطبی: ۱۳؍۲۸۹)\nدنیا اور پانی کے مابین تشبیہ کی بعض وجوہات واضح کریں.\nwords\nتَبِيدَوہ ہلاک ہو.\nصَعِيدًا زَلَقًاچٹيل زمين / جہاں قدم نہ ٹک سکتے ہوں/نہ وہاں کچھ اگتا ہو.\nغَورًازمين کي گہرائي ميں اترنے والا."],[299,"§الكهف\ndeeds\nاللہ تعالیٰ سے دل کی سلامتی مانگئے،حسد او ر تکبر سے اللہ کی پناہ مانگئے کیونکہ حسد اور تکبر کی بیماری نے ہی شیطان کو ہلاک کیا ہے.\nاپنے ان گناہوں کی تعیین کیجئے جنہیں آپ سنگین سمجھتے ہوں اور ان پر بکثرت اللہ سے مغفرت مانگئے،امید ہے کہ انہیں آپ کے نامہ اعمال سے صاف کردیا جائے.\nاپنی زندگی کے ایک اہم مقصد کے طور پر کسی بڑے نیک کام کا تعین کیجئے،پھر اس کے لئے بہترین انداز سے پیش قدمی شروع کردیجئے اور اس کی خاطر اللہ سے مدد بھی مانگئے تاکہ آپ غفلت میں نہ رہیں.\nguid\nمال اور اولاد کو نیک اعمال کی راہ میں رکاوٹ نہ بننے دیں بلکہ نیک اعمال میں انہی سے مدد لیجئے.\nجو دنیا میں اپنی نیکیوں اور برائیوں کو شمار کرتا رہیگا وہ قیامت کے دن نامہ اعمال دیکھ کر حیران وپریشان نہیں ہوگا.\nقیامت کے دن آپ کو اس وقت بڑی شرمندگی ہوگی جب پتہ چلے گا کہ تکلیفیں دور کرنے اور دعا قبول کرنے میں اللہ کا کوئی شریک نہیں.\nrefl\nٱلۡمَالُ وَٱلۡبَنُونَ زِينَةُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ\nیہی مال واولاد تھے جن پر عتبہ اور اس کے مالدار ساتھی فخر کرتے تھے (زينة الحياة الدنيا) دنیوی زیب وزینت توشہ آخرت کا حصہ نہیں ہے۔ علی بن ابی طالب رضی اللہ عنہ نے فرمایا: دولت اور بیٹے دنیا کی کھیتی ہیں او ر اچھے اعمال آخرت کی کھیتی ہیں اور کبھی کبھی اللہ تعالیٰ لوگوں کے لئے دونوں جمع کردیتا ہے۔(البغوی: ۳؍۳۴)\nدنیا کی کھیتی اور آخرت کی کھیتی کیا ہے؟\nوَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٌ أَمَلٗا ٤٦\nانسان کے لئے باقی رہنے والی،فائدہ مند اور خوش کرنے والی باقیات صالحات (ہمیشہ باقی رہنے والی نیکیاں) ہیں اور یہ واجب اور مستحب تمام نیکیوں کو شامل ہیں مثلاً حقوق اللہ، حقوق العباد،نماز،زکاۃ،صدقہ،حج،عمرہ،تسبیح،تحمید،تہلیل،قرأت ِقرآن،طلب ِ علم،نیکی کا حکم دینا،برائی سے روکنا،صلہ رحمی،والدین کے ساتھ حسن سلوک، بیویوں کے حقوق پورا کرنا،غلامو ں اور جانوروں کے حقوق کا احترام کرنا اور مخلوق کے ساتھ ہر لحاظ سے اچھا سلوک کرنا۔یہ تمام باقی رہنے والی نیکیاں ہیں۔ (السعدی: ۴۷۹)\nبعض باقی رہنے والی نیکیاں ذکر کیجئے.\nوَتَرَى ٱلۡأَرۡضَ بَارِزَةٗ\nیعنی زمین بالکل ظاہر کھلی ہوئی ہوگی،نہ تو کسی کی کوئی پہچان ہوگی اور نہ ہی کوئی ایسی جگہ جو کسی کو چھپاسکے بلکہ پوری مخلوق اپنے رب کے سامنے ظاہر ہوں گی۔ ان میں سے کوئی بھی اللہ سے چھپ نہیں سکے گا۔ (ابن کثیر: ۳؍۸۵–۸۶)\nاللہ کے اس فرمان: (وترى الأرض بارزة) میں کون سی دھمکی چھپی ہوئی ہے؟\nلَّقَدۡ جِئۡتُمُونَا كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةِۚ\nیعنی بغیر مال ودولت اور بغیر اہل وعیال کے۔ان کے ساتھ سوائے اعمال اور خیر وشر کی ان کی کمائی کے سوا کچھ نہ ہوگا۔ (السعدی؍۴۷۹)\nاللہ تعالیٰ کے فرمان: (لقد جئتمونا كما خلقناكم أول مرة) سے کیا مقصود ہے؟\nوَيَقُولُونَ يَٰوَيۡلَتَنَا مَالِ هَٰذَا ٱلۡكِتَٰبِ لَا يُغَادِرُ صَغِيرَةٗ وَلَا كَبِيرَةً إِلَّآ أَحۡصَىٰهَاۚ وَوَجَدُواْ مَا عَمِلُواْ حَاضِرٗاۗ وَلَا يَظۡلِمُ رَبُّكَ أَحَدٗا ٤٩\nامام قتادہ رحمہ اللہ نے فرمایا:لوگوں نے احصاء یعنی گناہوں کو شمار کرنے کی شکایت کی،کسی نے ظلم کی شکایت نہیں کی،پس تم چھوٹے گناہوں سے دور رہو کیونکہ یہی اکٹھاہوکر لوگوں کو ہلاک کردیتے ہیں۔ (القرطبی: ۱۳؍۴۵۹)\nصغیرہ گناہوں سے آدمی کب ہلاک ہوتا ہے؟\nوَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ\nاس سے سجدہ تکریمی اور تعظیمی مراد ہے۔ (ابن کثیر: ۳؍۸۷)\nفرشتوں کا آدم کو سجدہ کرنا عبادت تھا یا کچھ اور؟\nوَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ كَانَ مِنَ ٱلۡجِنِّ فَفَسَقَ عَنۡ أَمۡرِ رَبِّهِۦٓۗ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوۡلِيَآءَ مِن دُونِي وَهُمۡ لَكُمۡ عَدُوُّۢۚ بِئۡسَ لِلظَّٰلِمِينَ بَدَلٗا ٥٠\nاللہ تعالیٰ نے بنی آدم کو ان کے اور ان سے پہلے ان کے باپ دادا کے دشمن ابلیس سے خبردار کرتے ہوئے اور ان لوگوں کو پھٹکارتے ہوئے فرماتا ہے جو ابلیس کی پیروی کرتے ہیں اور خالق اور آقا کی مخالفت کرتے ہیں حالانکہ اسی نے انہیں اپنی مہربانی سے پیدا کیا،انہیں روزی دی اور غذا فراہم کی، ان سب کے باوجود انہوں نے ابلیس سے دوستی کرکے اللہ سے دشمنی کرلی۔(ابن کثیر: ۳؍۸۷)\nآیت کی روشنی میں بنی آدم میں سے کچھ لوگوں کی جہالت اور ان کی سرکشی کی وضاحت کیجئے.\nwords\nوَخَيرٌ أَمَلًاجس پر اللہ سے اچھي اميد رکھي جائے.\nفَفَسَقَپس وہ نکل گيا.\nعَضُدًامددگار.\nمَوبِقًاجہنم ميں ہلاک ہونے والا."],[300,"§الكهف\ndeeds\nسورۂ کہف میں مذکورہ قصوں میں سے کوئی قصہ پڑھئے اور اس میں موجود عبرتوں ونصیحتوں پر غوروفکر کیجئے.\nاپنی غفلت کے اسباب میں سے کسی ایک کا تعین کیجئے پھر پوری سنجیدگی کے ساتھ اسے چھوڑدینے کی کوشش شروع کردیجئے اور اللہ تعالیٰ سے دعا بھی مانگئے کہ آپ کو اس کا نعم البدل عطاکرے.\nکسی عالم سے ملاقات کے لئے جائیے اور ان سے کوئی مسئلہ سنئے یا ان کے پاس کوئی کتاب پڑھئے یا ان کے ادب اور سیرت میں سے کچھ سیکھئے کیونکہ یہ بھی باقی رہنے والی خیر میں سے ہے.\nguid\nبحث ومباحثہ اور جھگڑا انسان کی فطرت میں ہے۔آپ حتی المقدور اس سے بچنے کی کوشش کیجئے اور اس کا رخ خیر کی طرف موڑدیجئے.\nدعوت الی اللہ کے میدان میں ترغیب وترہیب کا اسلوب استعمال کیجئے.\nاللہ تعالیٰ کبھی گناہگار کے دل پر پردے ڈال دیتا ہے چنانچہ وہ قرآن میں تدبر نہیں کرپاتا اور نہ ہی اس کی مثالوں او ر قصوں کو سمجھ پاتا ہے حتی کہ توبہ کرلے.\nrefl\nوَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٖۚ وَكَانَ ٱلۡإِنسَٰنُ أَكۡثَرَ شَيۡءٖ جَدَلٗا ٥٤\nعلی رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے رات کے وقت انہیں اور فاطمہ رضی اللہ عنہا کو آواز دی اور پوچھا:کیا تم دونوں نماز نہیں پڑھ رہے ہو؟ علی نے کہا: اے اللہ کے رسول ! ہماری جانیں اللہ کے ہاتھ میں ہیں جب جگانا چاہتا ہے ہم جاگ جاتے ہیں۔ کہتے ہیں کہ میں نے جب یہ جواب دیا تو آپ صلی اللہ علیہ وسلم چلے گئے،ہمیں کوئی جواب نہیں دیا،پھر ہم نے سنا کہ آپ اپنی ران پر ہاتھ مارکر یہ آیت پڑھ رہے تھے: (وكان الإنسان أكثر شيء جدلًا). یعنی انسان بڑا جھگڑالو ہے۔ (ابن عاشور: ۱۵؍۳۴۸)\nاچھی بات کی نصیحت کرنے والے کا حتی الامکان خیال کیا جانا چاہئے۔ اس کی وضاحت کیجئے.\nوَكَانَ ٱلۡإِنسَٰنُ أَكۡثَرَ شَيۡءٖ جَدَلٗا ٥٤\nاکثر لوگ حق واضح ہوجانے کے بعد بھی باطل دلائل کے ساتھ حق کے بارے میں جھگڑتے ہیں اسی لئے اللہ تعالیٰ نے فرمایا: (وكان الإنسان أكثر شيء جدلًا) یعنی انسان بہت جھگڑالو اور بحثیں کرنے والا ہے۔حالانکہ یہ اس کے لائق ہے نہ یہ قرین ِانصاف ہے۔ اور اس کا اللہ پر ایمان نہ لانے کا سبب یہ نہیں ہے کہ اس کو بیان کرنے اور اس کی حجت وبرہان کو واضح کرنے میں کوئی کمی رہ گئی ہے بلکہ ظلم وسرکشی اس کے اس رویہ کا موجب ہے۔(السعدی: ۴۸۰)\nعلماء اور طلبا سے زیادہ بحث کرنے میں کیا کوئی بھلائی ہے؟اور کیا وجہ ہے کہ انسان اہل ِحق سے بہت زیادہ بحث کرتاہے؟\nوَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۚ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُواْ بِٱلۡبَٰطِلِ لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّۖ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَمَآ أُنذِرُواْ هُزُوٗا ٥٦\nوہ علمی آیات جن کی معرفت عقل سے ہوجاتی ہے کہ وہ رب کی نشانیاں ہیں۔ان کے درمیان اور ان آیات کے درمیان جو خوفناک چیزوں کے بارے میں خبر دے کر ڈرانے والی ہوتی ہیں جیسے کہ انبیاء علیہم السلام گناہگاروں کو عذاب ِالٰہی کی خبر سناتے ہیں۔ان دونوں میں فرق ہوتاہے چنانچہ اسے خبر اور دھمکی کے ذریعہ ہی جاناجاسکتا ہے۔(ابن تیمیہ: ۴؍۲۶۰)\nعام آیات اور ڈرانے والی آیات کے درمیان کیا فرق ہے؟\nوَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۚ\n(مبشرين) یعنی مومنوں کو جنت کی خوشخبری سنانے کے لئے ہی ہم رسولوں کو بھیجتے ہیں(ومنذرين) اور کافروں کو عذاب سے ڈرانے کے لئے۔(القرطبی: ۱۳؍۳۱۱)\nدعوت ِدین کے دواسلوب بتائیں جن کا ذکر آیت میں آیا ہے؟\nوَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعۡرَضَ عَنۡهَا وَنَسِيَ مَا قَدَّمَتۡ يَدَاهُۚ إِنَّا جَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۖ وَإِن تَدۡعُهُمۡ إِلَى ٱلۡهُدَىٰ فَلَن يَهۡتَدُوٓاْ إِذًا أَبَدٗا ٥٧\nاس آیت کریمہ میں اس شخص کے لئے دھمکی ہے جو حق کو پہچان لینے کے بعد اسے ترک کردے اور یہ کہ اس کے اورحق کے بیچ رکاوٹ کھڑی کردی جائے اور اس کے بعد اس کے لئے کوئی ایسی چیز نہ رہے جو اس کے حق میں اس سے بڑھ کر ڈرانے والی اور اس غلط روی سے اسے روکنے والی ہو۔ (السعدی: ۴۸۱)\nحق کوجان کر اس سے منہ موڑنے والے اور ایک جاہل کے درمیان بڑا فرق ہے۔آیت کی روشنی میں اسے واضح کریں.\nوَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعۡرَضَ عَنۡهَا وَنَسِيَ مَا قَدَّمَتۡ يَدَاهُۚ\nیعنی اس سے بڑا ظالم کوئی نہیں ہوسکتا جسے اس کے رب کی آیتوں کے ذریعہ نصیحت کی گئی ہو اور اس نے لاپرواہی سے کام لیا اور اسے قبول کرنے سے انکار کردیا۔ (القرطبی: ۱۳؍۳۱۲)\nاپنے آپ کے لئے سب سے بڑا ظالم کون ہے؟\nوَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبۡرَحُ حَتَّىٰٓ أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَيۡنِ أَوۡ أَمۡضِيَ حُقُبٗا ٦٠\nاس واقعہ سے مستنبط فوائد: علم میں اضافہ کی خاطر ایک عالم کا سفر کرنا اور اس کے لئے خادم اور دوستوں سے تعاون لینا۔ اہل ِفضل اور اہل ِعلم سے ملاقات کرنا گرچہ اس کے لئے لمبا سفر ہی کیوں نہ کرنا پڑے اور سلف صالحین کا یہی وطیرہ بھی تھا کیونکہ سفر کے ذریعہ ہی سے علم وآگہی کے میدان میں وہ اس بلند مقام تک پہنچے۔علوم وفنون میں انہوں نے گہرائی حاصل کی اور ساتھ ہی اجروثواب کے ساتھ ساتھ نیک نامی کے بھی مستحق ہوئے۔امام بخاری رحمہ اللہ فرماتے ہیں:جابر بن عبداللہ رضی اللہ عنہما نے صرف ایک حدیث کی خاطر عبداللہ بن اُنیس رضی اللہ عنہ سے ملاقات کے لئے ایک مہینہ کا سفر کیا۔(القرطبی: ۱۳؍۳۱۸)\nموسیٰ علیہ السلام کے سفر سے ایک طالب علم کیا سبق حاصل کر سکتاہے؟\nwords\nلِيُدحِضُواتاکہ اسے ختم کرديں.\nأَكِنَّةًڈھکن/ پردے.\nوَقرًابوجھ / بہرا پن.\nمَوئِلًاجائے پناہ / راہ نجات.\nحُقُبًاايک لمبا زمانہ."],[301,"§الكهف\ndeeds\nاللہ سے دعا مانگئے کہ آپ کو مخلوق پر رحم کرنے اور خالق کی معرفت حاصل کرنے کی توفیق دے کیونکہ جواپنے رب کی جتنی معرفت رکھتا ہے وہ اس کی مخلوق پر اتنا ہی مہربان ہوتا ہے.\nاللہ کی ولایت چند امور سے حاصل ہوتی ہے جن میں سے ایک اس کے چنیدہ نیک بندوں کے ساتھ رہنا ہے اور اس کے نیک بندوں کا ساتھ اچھے اخلاق سے ہی حاصل ہوتا ہے.\nآداب طالب علم کے موضوع پر کوئی کتاب پڑھئے،اس کی باتوں پر غورکیجئے اور ان پر عمل کیجئے.\nguid\nسننا،پڑھنا اور غورکرنا صرف اسباب ہیں ورنہ حقیقتاً علم دینے والا تو اللہ تعالیٰ ہی ہے.\nکبھی استاد اپنے شاگر د کی قوت برداشت اور بلند ہمتی جانچنے کی لئے بھی سرزنش کرتا ہے.\nطلب علم کی نیت سے سفر کی روداد پر مشتمل یہ قصہ پڑھئے بیشک اس میں بہت سے اسباق ہیں.\nrefl\nءَاتِنَا غَدَآءَنَا\nانسان کو کھانے میں خادم کو بھی شریک کرنا اور ایک ساتھ کھانا مستحب ہے کیونکہ (آتنا غداءنا) میں جمع کا صیغہ استعمال ہوا ہے جس سے بظاہر اس چیز کا پتہ چلتاہے کہ موسیٰ علیہ السلام کے ساتھ خادم نے بھی کھانا کھایاتھا۔ (السعدی؍۴۸۳)\nخادموں کے ساتھ طرز تعامل اور برتاؤ سے متعلق اس آیت کے اندر بعض آداب کی جانب تنبیہ کی گئی ہے۔ اس کی وضاحت کریں.\nفَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدۡ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبٗا ٦٢\nاس آیت میں اس بات کی دلیل ہے کہ انسان اپنی تکلیف اور بیماری کا اظہار کرسکتاہے۔اس سے تقدیر پر کوئی فرق نہیں پڑیگا بشرطیکہ یہ اظہار جزع فزع اور ناراضگی کے ساتھ نہ ہو۔ (القرطبی: ۱۳؍۳۲۲)\nکیا اپنی حالت کے بارے میں خبر دینا تقدیر پر اعتراض کرنا ہے؟\nوَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ\nیہاں برائی اور اس کے اسباب کی نسبت شیطان کی طرف اس لئے کی گئی ہے کیونکہ وہی برائیوں کو مزین کرکے پیش کرتا ہے،ورنہ ساری چیزیں اللہ کے ہی فیصلہ سے ہوتی ہیں۔ (السعدی؍۴۸۳)\nبھول جانے کو شیطان کی طرف کیوں منسوب کیا گیا ہے حالانکہ یہ تقدیر الٰہی سے ہوتاہے؟\nقَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدٗا ٦٦\nیہ اجباری والزامی سوال نہیں بلکہ شفقت ومہربانی والا سوال ہے ۔اور ایک طالب علم کی طرف سے عالم کے لئے ایسے ہی سوالات ہونے چاہئے۔ (ابن کثیر: ۳؍۹۴)\nآیت میں ایک ادب کی جانب رہنمائی کی گئی ہے جس سے آراستہ ہونا ایک طالب علم کے لئے ضروری ہے کہ وہ عالم کے ساتھ اس کا خیال رکھے۔ وہ کون سا ادب ہے؟\nقَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدٗا ٦٦\nنفع بخش علم ہی خیر وبھلائی کی طرف لے جانے والا ہے چنانچہ ہر وہ علم جس کے اندر بھلائی اور خیر کے راستوں کی طرف رہنمائی نیز برے راستوں سے تنبیہ پائی جائے تو وہی نفع بخش علم ہے اورجو اس کے علاوہ ہے یا تو وہ مکمل نقصان دہ ہے یا بے سود ہے جیسا کہ اللہ تعالیٰ نے فرمایا: (تعلِّمَنِ مما علمت رشدًا)(السعدی؍۴۸۴)\nموسیٰ علیہ السلام نے خضر علیہ السلام سے مطلق علم کانہ کہہ کر خیر وبھلائی والا علم کیوں طلب کیا؟\nقَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا ٦٧\nاس آیت میں علم کی ایک بنیاد کی طرف اشارہ ہے وہ یہ کہ معلم طالب علم کو سیکھے جانے والے علوم کے موضوعات کے تعلق سے ان پریشانیوں سے آگاہ کردے جن کا سامنا حصول علم کے دوران ہوسکتا ہے۔(ابن عاشور: ۱۵؍۳۷۲)\nآیت میں تعلیم کے ایک بنیادی امرکی طرف اشارہ ہے۔وہ کیا ہے؟\nقَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا ٦٧\nیعنی آپ میرے ساتھ نہیں رہ سکتے کیونکہ آپ میری طرف سے ایسی بہت ساری چیزیں دیکھیں گے جو آپ کی شریعت کے خلاف ہیں۔ (ابن کثیر: ۳؍۹۴)\nخضر علیہ السلام کے کاموں پر موسیٰ علیہ السلام کو صبر کیوں نہ ہوسکا؟\nwords\nأَوَينَاہم نے ٹھکانا ديا.\nنَبغِہم تلاش کر رہے ہيں.\nفَارتَدَّاپس وہ واپس پلٹے.\nخَرَقَهَاسوراخ کيا اس کو / ايک تختي اکھاڑ دي.\nإِمرًابرا کام.\nنُكرًابہت زيادہ برا کام."],[302,"§الكهف\ndeeds\nآج ایسا کوئی نیک عمل کیجئے جس کا فائدہ دوسروں کو ہو.\nآج کسی مظلوم یا کمزور کو ظلم سے بچانے کی کوشش کیجئے.\nاللہ تعالیٰ سے دعا کیجئے کہ آپ کی اولاد کو صالح بنائے.\nguid\nحصول علم کے لئے صبر شرط ہے.\nاللہ تعالیٰ اپنے نیک بندوں کے لئے کتنی بہترین تدبیر کرتا ہے! بظاہر تو تکلیف دہ معلوم ہوتی ہے لیکن بباطن رحمت ہوتی ہے.\nباپ کا اپنی اصلاح کرنا اولاد کی اصلاح اور ان کی بہترین روزی کا سبب ہے.\nrefl\nقَالَ إِن سَأَلۡتُكَ عَن شَيۡءِۢ بَعۡدَهَا فَلَا تُصَٰحِبۡنِيۖ قَدۡ بَلَغۡتَ مِن لَّدُنِّي عُذۡرٗا ٧٦\nیہاں موسیٰ علیہ السلام نے بھولنے کا عذرپیش نہیں کیا۔یا تو اس وجہ سے کہ وہ بھولے نہیں تھے بلکہ بلا سبب قتل جیسے بڑے گناہ سے روکنے کو وعدہ پورا کرنے پر فوقیت دی۔یا تو وہ بھول گئے تھے لیکن باربار بھول کا عذر پیش کرنے میں قباحت محسوس کررہے تھے۔(ابن عاشور: ۱۶؍۶)\nاس بار بھی موسیٰ علیہ السلام نے بھولنے کا عذر کیوں پیش نہیں کیا؟\nأَمَّا ٱلسَّفِينَةُ فَكَانَتۡ لِمَسَٰكِينَ يَعۡمَلُونَ فِي ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٞ يَأۡخُذُ كُلَّ سَفِينَةٍ غَصۡبٗا ٧٩\nیہاں ایک فقہی قاعدہ ہے،وہ یہ کہ: اگر کوئی شخص کسی کے مال میں اس کی مصلحت کے پیش نظر یا نقصان سے بچانے کی خاطر اس کی اجازت کے بغیر کوئی تصرف کرے تو جائز ہے گرچہ اس کے تصرف کی وجہ سے دوسرے کے مال کا تھوڑا سا نقصان ہی ہوجائے۔جیسا کہ خضر علیہ السلام نے کشتی میں نقص پیدا کرنے کے لئے اس میں سوراخ کردیا تاکہ ظالم بادشاہ اسے غصب نہ کرےتو اس طرح اگر کسی کے گھر یا مال میں آگ لگ رہی ہو یا غرق آب ہورہا یا کسی اور آفت کا شکار ہورہا ہو اور کچھ مال کو تباہ کرنے یا گھر کے کچھ حصہ کو توڑنے سے بقیہ کے بچنے کی امید ہو تو ایسا کرنا جائز بلکہ مشروع ہے۔ (السعدى: ۴۸۵)\nاس آیت سے علماء نے ایک بہت ہی اہم قاعدہ مستنبط کیا ہے۔وہ کیا ہے؟\nوَأَمَّا ٱلۡغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤۡمِنَيۡنِ فَخَشِينَآ أَن يُرۡهِقَهُمَا طُغۡيَٰنٗا وَكُفۡرٗا ٨٠\nامام قتادہ رحمہ اللہ نے کہا:یقینا وہ بچہ جب پیدا ہواتو اس کے ماں باپ خوش ہوئے اور جب قتل کیا گیا تو غمگین ہوئے لیکن اگر وہ جیتا رہتا تو وہ دونوں ہلاک ہوجاتے اس لئے آدمی اللہ کے فیصلہ پر راضی رہے کیونکہ ناپسندیدگی کے باوجود مومن کے حق میں اللہ کا فیصلہ اپنے من پسند فیصلہ سے اچھا ہی ہوتا ہے۔(ابن کثیر: ۳؍۹۶)\nدکھوں اور تکلیفوں میں مومن کو کیسا رویہ اپنانا چاہئے؟\nوَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا\nآیت میں اس بات کی دلیل ہے کہ نیک آدمی کی اولاد کی حفاظت ہوتی ہے،نیز اس کی عبادت کی برکت اولاد کو دنیا وآخرت دونوں جگہ پہنچے گی،بایں طور کہ آخرت میں انہیں اس کی شفاعت نصیب ہوگی اور جنت میں ان کے درجے بلند ہوں گے (یہاں تک کہ وہ اپنے نیک والد کے ساتھ جنت کے اونچے مرتبہ میں ہوں گے) تاکہ ان کے سبب اس کی آنکھیں ٹھنڈی ہوں۔ (ابن کثیر: ۳؍۹۷)\nآپ کا نیک عمل آپ کی اولاد کو بھی فائدہ پہنچاتا ہے۔ آیت کی روشنی میں اس کی وضاحت کیجئے.\nوَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا\nاس آیت میں دلیل ہے کہ اللہ تعالیٰ نیک آدمی کی اور اس کی اولاد کی حفاظت کرتا ہے گرچہ اولاد بعد والی پشت کی ہو۔اور مروی ہے کہ اللہ تعالیٰ نیک آدمی کی سات پشتوں کی حفاظت کرتاہے۔ (القرطبی: ۱۳؍۳۵۶)\nنیکی اور ثابت قدمی کا دنیا میں ملنے والا فائدہ کیا ہے؟\nفَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةٗ مِّن رَّبِّكَۚ\n(فأراد ربك) آپ کے رب نے چاہا۔ یہاں ارادے کی نسبت اللہ کی جانب کی گئی ہے کیونکہ یہ مستقبل کے معاملہ سے متعلق ہے جو ہم سے اوجھل ہے اور جسے صرف اللہ ہی جان سکتا ہے۔ جبکہ خضرعلیہ السلام نے یہاں (فأردت أن أعيبها)(میں نے اسے عیب دار بنانا چاہا۔) میں ارادے کی نسبت اپنی طرف کی کیونکہ اس میں عیب کا ذکر ہے۔ تو انہوں نے اللہ کے ادب واحترام میں اس کی جانب منسوب نہیں کیا جیسا کہ ابراہیم علیہ السلام کا یہ قول ہے: ﴿وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ﴾(سورۃ الشعراء: ۸۰) جب میں بیمار ہوتا ہوں تو وہی مجھے شفا دیتاہے۔ (ابن جزی: ۱؍۵۱۸)\nخضر علیہ السلام نے دیوار درست کرنے میں ارادے کی نسبت اللہ کی طرف کی جبکہ کشتی میں عیب لگانے کی بات میں ارادے کی نسبت اپنی طرف کی۔ اس میں کیا مصلحت ہے؟\nوَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرٗا ٨٢\n(وما فعلته عن أمري) میں نے یہ کام اپنے اختیار اور رائے سے نہیں بلکہ اللہ کے حکم سے کیا ہے۔ (البغوی: ۳؍۵۵)\nکیا عالم اور پیشوا اپنی مرضی سے کچھ بھی کرسکتے ہیں یا انہیں اللہ تعالیٰ کے احکام کی پیروی اور تابعداری کرنی چاہئے؟\nwords\nاستَطعَمَا أَهلَهَابطور ضيافت ان اہليان سے کھانا مانگا.\nيُرِيدُ أَن يَنقَضَّقريب ہے کہ گر جائے.\nبِتَأوِيلِانجام / عاقبت.\nيُرهِقَهُمَاان دونوں کو پھنسا دے/ مکلف کردے.\nزَكَاةًصلاح / طہارت کے اعتبارسے.\nوَأَقرَبَ رُحمًاان کے ساتھ احسان کرنے والا/ان کے ساتھ مہربان.\nذِي القَرنَينِايک نيک اور عادل بادشاہ جس کي حکومت مشرق سے مغرب تک تھي."],[303,"§الكهف\ndeeds\nذوالقرنین کا قصہ پڑھ کر اس سے تین فائدے اور عبرت کی باتیں نکالئے.\nیاجوج اور ماجوج کے فتنہ سے اللہ کی پناہ مانگئے.\nآج کسی کمزور ومحتاج کی مدد کیجئے.\nguid\nاگر آپ کوئی برائی یا باطل یا بگاڑ دیکھیں تو نصیحت کا فریضہ ادا کیجئے.\nہمیشہ اپنے اوپر اللہ تعالیٰ کے فضل وکر م کا اعتراف کرتے رہئے، چاہے آپ کتنے ہی معزز،مالدار اور اونچے عہدہ والے ہوجائیں.\nبڑے کام آپسی تعاون سے ہی انجام دئیے جاتے ہیں،کوئی اپنی رائے سے،کوئی مال سے اور کوئی محنت وکوشش سے تعاون کرتا ہے.\nrefl\nإِنَّا مَكَّنَّا لَهُۥ فِي ٱلۡأَرۡضِ وَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا ٨٤\nقرآن میں بیان کردہ یہ قصہ ذوالقرنین کے بارے میں کچھ بہت ہی اہم امور کی نشاندہی کرتا ہے۔ایک تو یہ کہ: ذوالقرنین نیک اور انصاف پسند بادشاہ تھے۔دوسرا یہ کہ: اللہ کی طرف سے انہیں الہام ہوتا تھا یعنی ان کے دل میں خیر کی باتیں ڈالی جاتی تھیں۔تیسرا یہ کہ ان کی حکومت بہت دوردراز کے علاقوں میں پھیلی ہوئی تھی۔چوتھا یہ کہ: وہ دوران فتوحات مغرب کی سمت میں بہت ہی دورکےایک نامعلوم علاقے میں پہنچ گئے تھے جسے قرآن نے (عَيْنٍ حَمِئَةٍ ) کہا ہے۔(ابن عاشور: ۱۶؍۲۰)\nاللہ تعالیٰ بعض دفعہ کسی بندے کو دنیا اور آخرت دونوں کی نعمتوں سے نواز دیتا ہے۔آیت سے اس بات کو ثابت کیجئے.\nوَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا ٨٤\nاللہ تعالیٰ نے انہیں جو اسباب وذرائع دئیے تھے،وہ اللہ اور اس کے رسول صلی اللہ علیہ وسلم نے ہمیں نہیں بتائے ہیں اور نہ ہی ان کے بارے میں قطعی علم پر مشتمل خبریں ہی وارد ہیں لہذا اس بابت توقف اختیار کرنے میں ہی بھلائی ہے۔ (السعدی: ۴۸۵)\nجن امور کی خبر اللہ او ر اس کے رسول صلی اللہ علیہ وسلم نے ہمیں نہیں دی ہے۔ان سے متعلق ہمیں کیا موقف اپنانا چاہئے؟\nوَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا ٨٤ فَأَتۡبَعَ سَبَبًا ٨٥\nاس کا معنی یہ ہے کہ: انہوں نے ان ذرائع واسباب کو درست طریقے سے استعمال کیا۔درحقیقت بہت سے لوگوں کے پاس اسباب ہوتے ہیں مگر وہ انہیں حق کے ساتھ استعمال نہیں کرتے اور بہت سے لوگوں کے پاس کوئی ذریعہ ہی نہیں ہوتا، تو اگر ذرائع کے ساتھ ان کے استعمال کی قدرت بھی ہو اور درست طریقے سے انہیں استعمال کیا جائے تو مقصد حاصل ہوتا ہے او ر اگر اسباب نہ ہوں یا ان کے استعمال کی قدرت نہ ہوتو مقصود حاصل نہیں ہوتا۔(السعدی: ۴۸۵)\nانسان اسباب وذرائع سے حقیقی معنی میں کب فائدہ اٹھاسکتا ہے؟\nقُلۡنَا يَٰذَا ٱلۡقَرۡنَيۡنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمۡ حُسۡنٗا ٨٦\nاس کا معنی یہ ہے کہ:اللہ تعالیٰ نے ذوالقرنین کو ان پر فتح دی، غلبہ عطاکیا اور ان پر حاکم بنادیا پھر انہیں اختیار دے دیا کہ اگر چاہیں تو کچھ کو قید کریں اور کچھ کوقتل اور اگر چاہیں تو احسان کرکے یا فدیہ لے کر چھوڑدیں۔تو انہوں نے اپنی رائے بتاکر اپنے عدل وایمان کا ثبوت دیا۔(ان کی رائے کا ذکر اگلی آیت میں ہے) (ابن کثیر: ۵؍۱۹۳)\nمومنین اللہ کی مخلوق پربہت مہربان ہوتے ہیں۔آیت سے اس بات کی وضاحت کیجئے.\nوَأَمَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗا فَلَهُۥ جَزَآءً ٱلۡحُسۡنَىٰۖ وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا يُسۡرٗا ٨٨\n(فله جزاء الحسنى ) یعنی:بدلہ میں اسے قیامت کے دن اللہ کے پاس جنت اور عمدہ حالت عطاہوگی۔ (وسنقول له من أمرنا يسرًا) یعنی: ہم اس کے ساتھ اچھا سلوک کریں گے،اچھی بات کریں گے اور اس کے معاملات آسان کردیں گے۔ یہ بات دلالت کرتی ہے کہ ذوالقرنین نیک،ولی صفت،عادل اور ذی علم بادشاہوں میں سے تھے کہ انہوں نے ہر ایک کے ساتھ اس کے حسب حال معاملہ کرکے اللہ کی مرضی کو پالیا۔ (السعدی:۴۸۵)\nنیک حاکم کے توفیق یافتہ ہونے کی کیا نشانی ہے؟\nقَالُواْ يَٰذَا ٱلۡقَرۡنَيۡنِ إِنَّ يَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِي ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰٓ أَن تَجۡعَلَ بَيۡنَنَا وَبَيۡنَهُمۡ سَدّٗا ٩٤ قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا ٩٥\nاس آیت میں اس بات کی دلیل ہے کہ رعایا کا تحفظ حاکم کا فریضہ ہے چنانچہ جو اموال فئ کے طور پر حاصل ہوتے ہیں اور دیگر عام مالی حقوق جو حاکم کے زیردست اور زیر نگرانی قومی خزانے میں جمع ہوتے ہیں ان اموال سے سرحدوں کی حفاظت کرے، رعایا کی ضرورتوں میں جو خلل ہے اسے پورا کرے، جن چیزوں کی اصلاح کی ضرورت ہے اس کی اصلاح کرے، حتٰی کہ اگر وہ سارے اموال رعایا کے حقوق کی ادائیگی اور عام اخراجات میں ختم ہوجائیں تو رعایا اپنے مال سے اس کی بھرپائی کرے، اور حاکم وقت تین شرطوں کی رعایت کرتے ہوئے رعایا کا بہتر خیال رکھے (۱) رعایا پر اپنے آپ کو ترجیح دیتے ہوئے کوئی چیز اپنے لئے خاص نہ کرے (۲) حاجتمندوں کو مقدم رکھے اور ان کی مدد کرے (۳) ان کی قدر ومنزلت کا لحاظ رکھتے ہوئے نوازشوں میں انصاف سے کام لے(القرطبی: ۱۳؍۳۸۴-۳۸۵)\nاللہ تعالیٰ کسی کو حاکم یا امیر بنائے تو اس پر اپنی رعایا یا ماتحتوں کے تئیں کیا فرائض ہوتے ہیں؟\nقَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا ٩٥\nذوالقرنین نے ان سے کہا: اللہ تعالیٰ نے مجھے جو حکومت اور قدرت دی ہے وہ تمہارے مالوں اور تعاون سے بڑھ کر ہے۔(القرطبی:۱۳؍۳۸۴)\nکیا ذوالقرنین اپنی بادشاہت سے فتنہ میں پڑے اور انہوں نے نعمتوں کے مالک اللہ تعالیٰ کو بھول کر اپنی قوت پر گھمنڈ کیا؟\nwords\nسَبَبًااسباب و وسائل جو ملکوں کي فتح کي طرف لے جاتے.\nفَأَتبَعَ سَبَبًااسباب کو سنجيدگي سے استعمال کيا.\nحَمِئَةٍگرم کالي مٹي والا/ دلدل.\nنُكرًابہت بڑا گناہ.\nخَرجًاأجرت / مزدوري.\nرَدمًابند/رکاوٹ."],[304,"§الكهف\ndeeds\nآج جب بھی کسی عبادت سے فارغ ہوں تو اللہ سے دعا کیجئے کہ آپ کی اس عبادت کو قبول کرے.\nشرک،بدعت اور دکھاوے سے اللہ کی پناہ مانگئے کیونکہ یہ اعمال کو خراب کرنے والی چیزیں ہیں.\nسورۂ کہف میں ذکر کردہ نیک اعمال شمار کیجئے اور ان میں سے کوئی ایک کیجئے۔امید ہے کہ اس کے سبب آپ کو جنت الفردوس مل جائے.\nguid\nجب بھی آپ کسی کی مدد کریں تو اللہ کی تعریف کرنا نہ بھولیں کہ اسی نے آپ کو اس کا رخیر کی توفیق دی ہے.\nجو عمل اللہ کی رضا کے موافق نہ ہو اور قبولیت کی شرط پر پورا نہ اترے اس کی کوئی حیثیت ہے نہ وزن.\nعمل صالح وہی ہے جو اللہ کے لئے خالص ہو اور صحیح دلیل کی روشنی میں رسول اللہ صلی اللہ علیہ وسلم کی سنت کے موافق ہو اور اس کے علاوہ ہر عمل مردود ہے گرچہ بظاہر درست لگے.\nrefl\nوَعَرَضۡنَا جَهَنَّمَ يَوۡمَئِذٖ لِّلۡكَٰفِرِينَ عَرۡضًا ١٠٠\nجہنم ان کے سامنے لاکر انہیں دکھائی جائیگی۔ تاکہ وہ اس میں داخل ہونے سے پہلے ہی اس کے عذاب اور سختیوں کو دیکھ لیں۔تو اس طرح ان کو جہنم میں جانے سے پہلے ہی دکھ اور تکلیف میں مبتلا کردیا جائیگا۔(ابن کثیر: ۳؍۱۰۴)\nقیامت کے دن جہنم میں جانے سے پہلے ہی محشر میں کافروں کو جہنم کیوں دکھائی جائیگی؟\nٱلَّذِينَ كَانَتۡ أَعۡيُنُهُمۡ فِي غِطَآءٍ عَن ذِكۡرِي وَكَانُواْ لَا يَسۡتَطِيعُونَ سَمۡعًا ١٠١\nوہ لوگ اللہ کی ان آیات کو نہیں سن سکتے جو ایمان کا ذریعہ بنتی ہیں اس وجہ سے کہ وہ قرآن اور رسول اللہ صلی اللہ علیہ وسلم سے بغض رکھتے ہیں اور معاملہ یہ ہے کہ جو شخص کسی سے نفرت کرتا ہو تو اس کی بات کو توجہ سے نہیں سنتا ہے تو اس طرح جب ان سے علم اور خیر کے راستے بند ہوگئے تو ان کے کان رہے نہ آنکھیں اور نہ ہی فائدہ پہنچانے والی عقل۔ (السعدی: ۴۸۷)\nوہ کون سا سبب ہے جس نے دین سے نفرت کرنے والوں کو اس قابل نہیں چھوڑا کہ قرآ ن کی آیات کو اس طور سے سن سکیں جس سے فائدہ ہو؟\nأَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓاْ أَن يَتَّخِذُواْ عِبَادِي مِن دُونِيٓ أَوۡلِيَآءَۚ إِنَّآ أَعۡتَدۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ نُزُلٗا ١٠٢\nعذاب کو مہمان نوازی کہنا استعارہ ہے جو طنز وتمسخر کے بطور ہے۔(ابن عاشور: ۱۶؍۴۵)\nعذاب کو مہمان نوازی کہنے کی کیا وجہ ہے؟\nقُلۡ هَلۡ نُنَبِّئُكُم بِٱلۡأَخۡسَرِينَ أَعۡمَٰلًا ١٠٣ ٱلَّذِينَ ضَلَّ سَعۡيُهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ يَحۡسَبُونَ أَنَّهُمۡ يُحۡسِنُونَ صُنۡعًا ١٠٤\nاس میں اس بات کی دلیل ہے کہ کچھ لوگ یہ سمجھ کر کوئی عمل کرتے ہیں کہ وہ حق پر ہیں اور ان کا وہ عمل درست ہے لیکن درحقیقت ان کا عمل ضائع ہوجاتا ہے او ر اس کے ضیاع کی وجہ یا تو عقیدہ کا بگاڑ ہوتی ہے یا دکھاوا۔(القرطبی: ۱۳؍۳۹۲)\nبعض دفعہ بندے کا عمل برباد ہوجاتا ہے اور اسے احساس بھی نہیں ہوتا۔اس کی کیا وجوہات ہوسکتی ہیں؟\nأُوْلَٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَلِقَآئِهِۦ فَحَبِطَتۡ أَعۡمَٰلُهُمۡ فَلَا نُقِيمُ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَزۡنٗا ١٠٥\nان کے لئے میزان قائم نہ کرنے کا سبب دراصل ان کے اعمال کا برباد ہوجانا ہے۔اس لئے کہ اعمال برباد ہوجانے کی وجہ سے وہ یوں قلاش ہوگئے کہ ان کے پاس نیک اعمال کے نام پر کچھ بچا ہی نہیں۔(ابن عاشورء:۱۶؍۴۸)\nقیامت کے دن کافروں کے لئے میزان کیوں قائم نہیں کیا جائیگا؟\nلَا يَبۡغُونَ عَنۡهَا حِوَلٗا ١٠٨\nجنتی جنت سے کہیں اور جانے کے بارے میں سوچیں گے بھی نہیں کیوں کہ وہ وہاں صرف خوشیاں،اپنی مرضی کی چیزیں،دل کا سرور اور اطمینان وراحت ہی پائیں گے اور جن نعمتوں میں وہ ہوں گے ان سے ہٹ کر کسی اور نعمت کا تصور بھی نہ کریں گے۔ (السعدی: ۴۸۸)\nجنتی جنت سے کہیں اور جانے کے بارے میں کیوں نہیں سوچیں گے؟\nقُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ\nعبداللہ بن عباس رضی اللہ عنہما کہتے ہیں:اللہ نے اپنے رسول صلی اللہ علیہ وسلم کو تواضع سکھائی ہے تاکہ آپ اپنے کو دوسروں سے بڑا نہ سمجھیں چنانچہ حکم دیا کہ آپ اس بات کا اعتراف کریں کہ:میں تمہاری ہی طرح آدمی ہو ں بس مجھ میں اور تم میں فرق یہ ہے کہ اللہ نے مجھ پر وحی نازل کرکے میری تخصیص کی اور اس کے ذریعہ مجھے عزت بخشی ہے۔(البغوی: ۳؍۷۰)\nاس آیت کی روشنی میں تواضع کی اہمیت پر دلالت کرنے والی بات بیان کیجئے.\nwords\nدَكَّاءَمنہدم / زمين سے ملا ہوا.\nفَحَبِطَتپس تباہ ہوگئے.\nحِوَلًاجگہ تبديل کرنا.\nلَنَفِدَضرور ختم ہو جائے.\nمَدَدًاسياہي."],[305,"§مريم\ndeeds\nکسی ایسے معاملے کی تحدید کیجئے جو آپ پر دشوار ہو پھراس سے نجات حاصل کرنے کے لئے اللہ سے حسن ِظن رکھتے ہوئے چپکے چپکے دعامانگئے.\nاللہ سے دعا کیجئے کہ وہ آپ کو نیک اولاد سے نوازے اور آپ کی اولاد کو اولیاء اللہ میں شامل کرے.\nخصوصی طور سے صبح اور شا م کے وقت میں اللہ کا ذکر کثرت سے کیجئے.\nguid\nاللہ تعالیٰ سے اچھا گمان رکھئے کیونکہ اللہ بندے کے ساتھ ویسا ہی معاملہ کرتا ہے جیسا بندہ اس کے متعلق گمان رکھتا ہے.\nغورکیجئے کہ اللہ تعالیٰ کس طرح دعا کرنے والوں کی دعا قبول کرتا ہے۔یہ غوروفکر آپ کواور زیادہ عاجزی کے ساتھ گڑگڑاکر دعا مانگنے کا حوصلہ دیگا.\nاپنی خواہشات کو اپنی صلاحیتوں سے مت ناپئے، بلکہ اللہ تعالیٰ کی قدرت سے ناپئے (کہ یہ بات اللہ کی قدرت سے بعید نہیں ہے).\nrefl\nذِكۡرُ رَحۡمَتِ رَبِّكَ عَبۡدَهُۥ زَكَرِيَّآ ٢\nاللہ تعالیٰ نے زکریا علیہ السلام کو بندے کی صفت سے متصف کیا، یہ ان کے لئے اعزاز بھی ہےاور خبر بھی کہ آپ اللہ کے خاص اور مقرب بندے ہیں۔ (ابن جُزی: ۲؍۳)\nاللہ تعالیٰ نے زکریا علیہ السلام کو بندہ کی صفت سے کیوں متصف کیا؟\nإِذۡ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيّٗا ٣\n(إذ نادى ربه) جس وقت انہوں نے اپنے رب کو پکارا (نداءً خفيًا)یعنی چپکے چپکے پکاراکیونکہ اللہ تعالیٰ جس طرح بلند آواز سنتا ہے اسی طرح چپکے چپکے اور آہستہ آواز بھی سنتا ہے اور چپکے سے دعا کرنا اخلاص کے زیادہ قریب اور ریا ونمو دسے زیادہ پاک ہے اور اس لئے بھی کہ کہیں اس عمر میں اولاد مانگنے پر لوگ ملامت نہ کریں۔ (ابن جزی: ۲؍۳)\nیہاں زکریا علیہ السلام کی دعا کو “چپکے چپکے” کی صفت سے بیان کرنے میں بہت ہی عمدہ مناسبت ہے جس میں کئی اہم نکات ہیں۔انہیں بیان کیجئے.\nقَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ مِنِّي وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبٗا\nزکریا علیہ السلام نے اپنی کمزوری اور عاجزی کو وسیلہ بنایاجو اللہ تک پہنچنے کے لئے محبوب ترین وسیلوں میں سے ہے کیونکہ اس سے ہر طرح کی طاقت او ر قوت سے براء ت کا اظہار ہوتا ہے نیز اللہ تعالیٰ کی طاقت وقوت سے دل کے جڑنے کا پتہ چلتا ہے۔ (السعدی؍۴۸۹(\nزکریا علیہ السلام کے قصہ میں دعا کا وہ مفید اور کارگر وسیلہ کون سا ہے جس کی وضاحت آئی ہے؟\nقَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ مِنِّي وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبٗا وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيّٗا ٤\nعلماء نے کہا ہے کہ آدمی کے لئے یہ مستحب ہے کہ وہ دعا میں اپنے اوپر کی گئی اللہ تعالیٰ کی نعمتوں کو یاد کرے، نیز ان چیزوں کا بھی ذکر کرے جو خشوع وخضوع کے مناسب ہوں کیونکہ (وهن العظم مني)کے اندر خشوع وخضوع کا اظہار ہے اور (ولم أكن بدعائك رب شقيًا) کے اندر ان کی دعاؤں کی قبولیت کے سلسلہ میں اللہ تعالیٰ کے عمومی احسانات کا اظہار ہے۔ مفہوم یہ ہے کہ میں تجھ سے دعا کرکے کبھی بدبخت نہیں ہوا یعنی جب جب میں نے تجھے پکارا تو نے کبھی مایوس نہیں کیا یعنی اے اللہ! تو نے مجھے پہلے ہی سے دعا کی قبولیت کا عادی بنادیا ہے۔ (القرطبی: ۱۳؍۴۰۹)\nاللہ تعالیٰ سے دعا کرنے والے اور گڑگڑانے والے کو کیا کرنا چاہئے؟اس کی وضاحت کیجئے.\nوَإِنِّي خِفۡتُ ٱلۡمَوَٰلِيَ مِن وَرَآءِي وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا فَهَبۡ لِي مِن لَّدُنكَ وَلِيّٗا ٥ يَرِثُنِي وَيَرِثُ مِنۡ ءَالِ يَعۡقُوبَۖ\nدراصل زکریا علیہ السلام کو یہ خوف لاحق ہوا کہ کہیں ان کی وفات کے بعد ان کے قرابتدار لوگوں کے ساتھ براسلوک نہ کریں اسی لئے انہوں نے اللہ سبحانہ وتعالیٰ سے ایک ایسے بچے کی دعا کی جو ان کے بعد نبی بنے تاکہ وہ وحی الٰہی کی روشنی میں اپنی نبوت کے ذریعہ لوگوں پر حکمرانی کرے اور ان کی یہ دعا قبول کرلی گئی۔انہیں اس بات کا ڈر نہیں تھا کہ ان کے قرابتدار ان کے مال کو وراثت میں تقسیم کرلیں گے کیونکہ نبی کا مقام ومرتبہ اس بات سے کہیں بلند ہے کہ اسے اپنے مال ودولت پراس درجہ خوف لاحق ہو۔ (ابن کثیر: ۳؍۱۰۹)\nکیا اللہ کے نبی زکریا علیہ السلام کو اس بات کا خوف تھا کہ ا ن کی وفات کے بعد ان کی دولت ان ورثاء کے درمیان تقسیم ہوجائیگی جو ان کی حقیقی اولاد نہیں ہیں جیسا کہ آج کل دنیا پرست لوگ کرتے ہیں؟ اور کیا اصلا انبیاء کی (مالی) وراثت تقسیم ہوتی ہے؟\nيَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسۡمُهُۥ يَحۡيَىٰ لَمۡ نَجۡعَل لَّهُۥ مِن قَبۡلُ سَمِيّٗا ٧\nآیت کے اندر جس خوشخبری کا ذکر ہے اس میں تین چیزیں شامل ہیں:پہلی چیز آپ کی دعا قبول ہوگئی جو ایک کرامت ہے۔دوسری چیز اولاد کا پانا جو ایک قوت اور سہارا ہے اور تیسری چیز اس بچے کے نام کی انفرادیت اور انوکھا پن ہے۔(القرطبی: ۱۳؍۴۱۷)\nزکریا علیہ السلام کے دعا کرنے اور گڑگڑانے کے بعد اللہ تعالیٰ نے آپ کو کن کن خوشخبریوں سے نوازا؟\nقَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِيّٗا ٨\nیہ پُر تعجب او ر عقل سے بعید بات ہے کہ زکریا علیہ السلام کے بڑھاپے اور ان کی بیوی کے بانجھ ہونے کے باوجود انہیں اولاد نصیب ہو لیکن چونکہ انہیں یہ علم تھا کہ اللہ تعالیٰ اس بات پر قادر ہے اسی لئے انہوں نے پہلے اولاد کی دعا مانگی (پھر خوشخبری ملنے پر) انہوں نے تعجب کا اظہار کیا کیونکہ یہ عادتاً بہت ہی نایاب اور نادر چیز ہے۔ اور یہ بھی کہا گیا ہے کہ جس عمر میں انہوں نے اولاد کی دعا مانگی تھی اس وقت اولاد ہونے کی امید تھی لیکن یہ دعا کئی سال بعد اس وقت قبول ہوئی جب وہ بوڑھے ہوچکے تھے۔(ابن جزی: ۲؍۴)\nاللہ تعالیٰ کی طرف سے اولاد کی خوشخبری ملنے پر زکریا علیہ السلام کو کیسے تعجب ہوا حالانکہ اس کی دعا تو آپ نے خود ہی کی تھی؟\nwords\nنَادَىپکارا.\nوَهَنَکمزور ہوگيا.\nالمَوَالِيَقريبي رشتہ دار.\nعَاقِرًاجو جنم نہ ديتي ہو.\nعِتِيًّابڑھاپے کي انتہاء.\nبُكرَةً وَعَشِيًّاصبح اور شام."],[306,"§مريم\ndeeds\nدین کے احکام پر پوری قوت سے کاربند رہنے کی کوشش کیجئے اور ان پر عمل کرنے میں لہو ولعب سے کام نہ لیجئے.\nجبرئیل علیہ السلام کو انسانی شکل میں دیکھتے ہی مریم گھبراگئیں اور فوراً ہی صر ف اللہ سے فریاد کی، کسی اور سے نہیں.\nکوئی بھی کام کرنے کے لئے اسباب اختیار کیجئے۔ (اور اللہ پر توکل کیجئے) اسباب کے بغیر صرف خیالی بھروسہ مت کیجئے.\nguid\nاپنے ماں باپ کو کوئی ایسی چیز پیش کیجئےجو وہ پسند کرتے ہوں.\nجس کے شر سے آپ گھبراتے ہوں تو آج اس سے اللہ کی پناہ مانگئے.\nنہار منہ سات کھجوریں کھائیے.\nrefl\nوَبَرَّۢا بِوَٰلِدَيۡهِ وَلَمۡ يَكُن جَبَّارًا عَصِيّٗا ١٤\nاللہ تعالیٰ کا فرمان ہے کہ یحییٰ علیہ السلام والدین کے فرمانبردار تھے،دونوں کی بات ماننے اور ان سے محبت کرنے میں سبقت کرنے والے تھے اوران کے نافرمان نہیں تھے(ولم يكن جبارًا عصيًا) یعنی انہوں نے اپنے رب او ر اپنے والدین کی فرمانبرداری میں کبھی تکبر سے کام نہیں لیا بلکہ ہمیشہ اللہ تعالیٰ اور والدین کی فرمانبرداری میں خاکساری ظاہر کی۔انہیں جس کا م کا حکم ملتا اسے بجالاتے اور جس کام سے روکا جاتا اس سے رک جاتے۔ نہ تو آپ نے اپنے رب کی نافرمانی کی اور نہ ہی والدین کی۔(طبری: ۱۸؍۱۶۰)\nوہ دوحق کون سے ہیں جن کاذکر اس آیت میں کیا گیا؟\nوَسَلَٰمٌ عَلَيۡهِ يَوۡمَ وُلِدَ وَيَوۡمَ يَمُوتُ وَيَوۡمَ يُبۡعَثُ حَيّٗا ١٥\nسفیان بن عُيينہ رحمہ اللہ نے فرمایا ہے کہ: تین جگہیں ایسی ہیں جہاں آدمی سب سے زیادہ وحشت میں ہوتا ہے:جس دن پیدا ہوتا ہے اس وقت اپنے آپ کو اس جگہ سے باہر پاتا ہے جہاں وہ پہلے تھا،جس دن اس کی موت ہوتی ہے اس وقت وہ ایسے لوگوں کو دیکھتا ہے جنہیں پہلے کبھی نہیں دیکھاتھااور جس دن اسے اٹھایا جائیگا اس وقت وہ اپنے آپ کو بڑے میدان ِمحشر میں دیکھے گا۔ چنانچہ ان ساری جگہوں پر اللہ تعالیٰ نے یحییٰ علیہ السلام کے ساتھ اکرام واحسان کیا۔ اسی لئے آپ کے ساتھ سلامتی کو خاص کیا گیا ہے۔ (ابن کثیر:۳؍۱۱۱)\nیحییٰ علیہ السلام کے ساتھ آیت میں مذکورہ تینوں جگہوں پر سلامتی کو خاص کیوں کیا گیا ہے؟\nقَالَتۡ إِنِّيٓ أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيّٗا ١٨\nمریم علیہا السلام نے فرشتے کو اللہ کی یاد دلائی۔بچاؤ اور دفاع کے وقت یہی مشروع ہے کہ ایسے موقع پر سب سے پہلے آسان ترین طریقہ اپنایا جائے۔ یہی وجہ ہے کہ انہوں نے پہلے فرشتے کو اللہ کا خوف دلایا۔ (ابن کثیر:۳؍۱۱۳)\nانسان پر حملہ آور اور ظالم کو روکنے کے لئے سب سے بہتر طریقہ کیا ہے؟\nقَالَتۡ إِنِّيٓ أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيّٗا ١٨\nمریم علیہا السلام نے اللہ کی دوسری صفات کو چھوڑ کر صفت ”رحمن“ کو ذکر کیا کیونکہ اس وقت انہوں نے آنے والے شخص کو بدکار اور فاجر سمجھا چنانچہ ان کی چاہت ہوئی کہ اللہ تعالیٰ اس شخص کو ان سے دورہٹاکر ان پر رحم فرمائے۔ (ابن عاشور: ۱۶؍۸۱)\nمریم علیہا السلام نےاللہ کی دوسری صفات کو چھوڑکر صفت ”رحمن“ ہی کو خاص کر کیوں ذکر کیا؟\nوَلِنَجۡعَلَهُۥٓ ءَايَةٗ لِّلنَّاسِ\nیہ آیت اللہ تعالیٰ کی کمال ِقدرت پر دلالت کرتی ہے اور اس بات پر بھی کہ اسباب بذات خودمؤثر نہیں ہوتے بلکہ ان کا اثر صرف اللہ تعالیٰ کی تقدیر سے ہوتا ہے۔اسی لئے اللہ تعالیٰ اپنے بندوں کو کچھ ایسی کرامات دکھاتا ہے جو عام اسباب کے خلاف ہوتی ہیں تاکہ ایسا نہ ہو کہ لوگ اسباب کے سہارے بیٹھ جائیں اور اسباب کو مقدر کرنے والے مسبّب الاسباب یعنی ذات باری تعالیٰ سے بے پرواہ ہوجائیں۔ (السعدی: ۴۹۱)\nمریم علیہا السلام اور ان کے بیٹے کا قصہ ایسا ہے جو دیگر دنیوی اسباب کو چھوڑکر صرف اللہ تعالیٰ سے دلوں کو جوڑ دیتا ہے۔ اس کی وضاحت کیجئے.\nوَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا ٢٥\nاس آیت سے بعض لوگوں نے یہ استدلال کیا ہے کہ آدمی کے لئے ضروری ہے کہ وہ رزق کی تلاش میں اسباب اختیار کرے کیونکہ اللہ تعالیٰ نے مریم علیہا السلام کو کھجور کے درخت کو ہلانے کا حکم دیا تھا۔ (ابن جزی: ۲؍۶)\nآیت سے پتہ چلتاہے کہ بندے پر واجب ہے کہ وہ رزق کی تلاش میں اسباب کو اپنائے۔اس کی وضاحت کیجئے.\nوَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا ٢٥ فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ\nبعض علماء نے اس آیت سے یہ استدلال کیا ہے کہ عورتوں کے لئے حالت ِنفاس میں سب سے بہتر چیز تازہ کھجور یعنی رُطَب ہے اس کی وجہ یہ بتائی ہے کہ اگر ایسی عورتوں کے لئے رطب سے زیادہ بہتر کوئی چیز ہوتی تو اللہ تعالیٰ عیسیٰ علیہ السلام کی ولادت کے وقت مریم علیہا السلام کو ضرور وہ چیز کھلاتا۔یہ بات ربیع بن خُثَیم وغیرہ نے کہی ہے۔ (شنقیطی: ۳؍۳۹۹)\nقرآن پاک اس آیت کے اندر ایک طبی طریقہ پیش کرتا ہے۔وہ کیا ہے؟\nwords\nخُذِ الكِتَابتورات.\nبِقُوَّةٍسنجيدگي اور اجتہاد کے ساتھ حفظ فہم اور عمل کے اعتبار سے.\nالحُكمَحکمت / حسن فہم و عمل.\nوَحَنَانًااور رحمت و محبت سے.\nانتَبَذَتگوشہ نشين ہوگئي/ دور ہو گئي.\nفَأَجَاءَهَااسے لے آيا؛ مجبور کرديا.\nالمَخَاضُدرد زہ.\nسَرِيًّاپاني کي نہر/ چشمہ.\nجَنِيًّاتازہ کھجوريں/اسي گھڑي کي چني ہوئي."]])